		["{npc:5137} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5137} la recoge cuando tu habilidad de {skill:182} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5392} la recoge en cuanto tu habilidad de {skill:186} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:5392}, at the depot"] = "{npc:5392}, en el depósito",
		["{npc:5413} in {zone:1453} takes it"] = "La recoge {npc:5413} en {zone:1453}",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} entrena a los guerreros en {object:2100}, cerca de la tienda de Osric; el tranvía de {zone:1455} llega a {object:28027}, al norte. {npc:6089} y {npc:6090} están juntos junto a {object:2152}. {npc:6090} pelea contigo por su jarra. Si {npc:5480} no te ofrece {quest:1638}, ve directamente con {npc:6089}: te da {quest:1639} sin ella.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de los magos de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:5505} in {zone:1453}; {zone:1426} has no druid trainer"] = "{npc:5505} en {zone:1453}; {zone:1426} no tiene instructor de druidas",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recoge {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:6291} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6291} la recoge cuando tu habilidad de {skill:393} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6806}, inside"] = "{npc:6806}, dentro",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, al lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. La {item:10438} está en la nieve al sur, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: cógelos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, bajo la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:836}, inside {area:77}; below ground"] = "{npc:836}, dentro de {area:77}; bajo tierra",
		["{npc:837}, inside {area:77}"] = "{npc:837}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, en la puerta, a la salida; dentro",
		["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, junto a la puerta de {area:77}; dentro",
		["{npc:8508}, on the dock"] = "{npc:8508}, en el muelle",
		["{npc:912}, the warrior trainer"] = "{npc:912}, el instructor de guerreros",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, el instructor de magos, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: su gargantilla y The Binding están en la vuelta por el este de Elwynn de {zone:1436}",
		["{zone:1426}: kill these as you meet them"] = "{zone:1426}: mata a estos según te los encuentres",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tía\" Bernice Pedregosa",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Vuelve con {npc:6122} el Vinculaoscuro. Usa el {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que aparece.",
		["Back to {zone:1429}"] = "De vuelta a {zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "Billy Maclure juega en {area:64}, al este de la mina.",
		["Chunks of Boar Meat"] = "Trozos de carne de jabalí",
		["Class trainer"] = "Instructor de clase",
		["Crystal Kelp Fronds"] = "Hojas de kelp de cristal",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Los Zahoríes bribones Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en el poblado múrloc de la orilla noreste.\nCuidado: los Zahoríes bribones lanzan hechizos a distancia y un {npc:6866} (10) recorre la orilla con ellos: atráelos de uno en uno.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Los Matones Defias acampan en el claro al este de la abadía y por el lado este del valle.",
		["Druid trainer"] = "Instructor de druidas",
		["Follow the hills south to the tower, on the road west."] = "Sigue las colinas hacia el sur hasta la torre, en el camino al oeste.",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}.\nNow and then a kobold here drops a {quest:91741}: right-click it and hand it to {npc:951} on your next Abbey stop."] = "Sigue el sendero al norte hasta la mina. Los obreros kóbold ({npc:257}) pululan fuera; cualquier kóbold del valle puede soltar {object:83763}.\nDe vez en cuando un kóbold de aquí suelta {quest:91741}: haz clic derecho en él y dáselo a {npc:951} en tu próxima parada en la abadía.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Sigue el camino hacia el este pasando {area:91} hasta el puente. Acaba con los Merodeadores y Osos del bosque jóvenes de alrededor del río, al sur del puente.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:5497} está en el Sagrario del Mago, la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Sigue el camino hacia el sur, fuera de {area:87}, hasta {area:64}. {npc:251} Maclure espera junto a la casa.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Sigue el camino al sur hasta {area:120}, a la entrada de {zone:1436}. {npc:963} está afuera del cuartel; {npc:955}, adentro. Solo tiene {quest:91738} mientras llevas el {item:247824}: háblale y pasa directo a la entrega.",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Sigue el camino al oeste de vuelta a {area:87}; {npc:6306} está en la orilla del lago antes del pueblo. {npc:377} (sacerdotes), {npc:328} (magos) y {npc:917} (pícaros) están arriba en la posada: sube por la escalera de adentro, la flecha no distingue los pisos.",
		["From level 5 {npc:248362}, a level 3 elite, is two levels under you: he waits down the second turn on the right inside the mine.\nCareful: clear the Laborers around him first and fight him at full health."] = "Desde el nivel 5, {npc:248362}, un élite de nivel 3, está dos niveles por debajo de ti: espera en el segundo recodo a la derecha dentro de la mina.\nCuidado: limpia primero a los peones de su alrededor y lucha con la salud completa.",
		["From level 5: Kelsey's {quest:91752}. {npc:248362} (3, elite) is two levels under you then."] = "Desde el nivel 5: {quest:91752} de Kelsey. {npc:248362} (3, élite) estará entonces dos niveles por debajo de ti.",
		["Fun with Elementals: {npc:248464}"] = "Álbum de fotos: diversión con elementales: {npc:248464}",
		["He stands by the river west of the farm."] = "Está junto al río, al oeste de la granja.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Regresa por {area:87} y hacia el este por el camino hasta {area:62}. {npc:881} (nivel 9) está junto a la granja.",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Sal de {area:87} hacia el este por la orilla del lago. {npc:383} está en la orilla al noreste del pueblo.",
		["Heal and fortify {npc:12423}"] = "Sana y fortalece a {npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Si te saltaste {quest:91740}, mata enemigos aquí hasta el nivel 8.85 para seguir el plan de la ruta.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Si te saltaste {quest:91775}, mata enemigos aquí hasta el nivel 8.39 para seguir el plan de la ruta.",
		["Inside"] = "Dentro",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right.\nNow and then a Laborer drops a {quest:91741}: right-click it and hand it to {npc:951} at the Abbey after the mine.\nCareful: {npc:248362} (3) is elite: below level 5, leave him be."] = "Los peones kóbold ({npc:80}) trabajan en los túneles de la mina. {npc:248362} espera en el segundo recodo a la derecha.\nDe vez en cuando un peón suelta {quest:91741}: haz clic derecho en él y dáselo a {npc:951} en la abadía después de la mina.\nCuidado: {npc:248362} (3) es élite: antes del nivel 5, déjalo en paz.",
		["Large Candles"] = "Velas grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} al pie de ella.",
		["Level 8.39"] = "Nivel 8.39",
		["Level 8.85"] = "Nivel 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Libros perdidos: Mineros kóbold y Tuneladores",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Magos: {npc:198}, el instructor de magos, está arriba en la Abadía: sube por la escalera de adentro, la flecha no distingue los pisos.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Los múrlocs y los Correcorrientes múrloc ocupan la orilla este; los Montones de chatarra están en su campamento. Cuidado: los múrlocs están muy juntos, así que es fácil atraer a dos o tres a la vez en un combate: atráelos de uno en uno desde el borde del campamento y no persigas a ninguno hasta el siguiente grupo.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Al noreste del campamento maderero. Los Zahoríes bribones Defias acampan en las orillas del lago.\nCuidado: los Zahoríes bribones lanzan hechizos a distancia y un {npc:6866} (10) recorre la orilla con ellos: atráelos de uno en uno.",
		["Painted Gnoll Armbands"] = "Bandas gnoll pintadas",
		["Red Burlap Bandanas"] = "Arpilleras rojas",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Los Jabatos Zarparrío y los Avanzados ocupan las colinas al sur del cuartel, a lo largo de la frontera con {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["Shaman trainer"] = "Instructor de chamanes",
		["She stands by her cart at the vineyard east of the Abbey."] = "Está junto a su carro, en el viñedo al este de la abadía.",
		["She stands outside the mine entrance. Her next errand, {quest:91752}, sends you after {npc:248362} inside, a level 3 elite: the guide gives it from level 5, when he is two levels under you."] = "Está fuera de la entrada de la mina. Su siguiente recado, {quest:91752}, te manda dentro a por {npc:248362}, un élite de nivel 3: la guía lo da desde el nivel 5, cuando está dos niveles por debajo de ti.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Manzanas rojas lustrosas, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Siéntate (/sentarse) junto a su hoguera hasta tener {spell:1229451}",
		["South down the road to the {area:64}."] = "Al sur por el camino hasta {area:64}.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["Tame {npc:1922}"] = "Domestica un {npc:1922}",
		["Tame {npc:524}"] = "Domestica un {npc:524}",
		["Tame {npc:822}"] = "Domestica un {npc:822}",
		["The Defias camp"] = "El campamento Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Las trampas de pesca ({object:694772}) están en la orilla oeste del lago.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La granja Pedregosa está al oeste de la mina. La vieja Pedregosa y la \"Tía\" Bernice están junto a la casa.\nElla está sentada dentro de la casa de la granja.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "El campamento está al noreste del puente. Los Haces de leña están por el campamento y en el bosque al norte.\nCuidado: Zarpaolmo, un gnoll élite de nivel 12, recorre el bosque y las colinas desde el campamento maderero al norte hasta {area:86} y los campamentos gnoll: apártate de él cuando lo veas venir.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Las cajas de uvas están en los viñedos, detrás de los Defias. {npc:103} espera junto a la cabaña del extremo este del valle.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The kobold camp"] = "El campamento kóbold",
		["The lake shore"] = "La orilla del lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.\nCuidado: {npc:471} (7-10), las Arañas mineras (7-9) y {npc:248474} (7) son élites del fondo de la mina: atrae a los kóbolds de uno en uno cerca de la entrada y retírate si viene un élite; son más fáciles con un amigo.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mina está al oeste de los viñedos. Los Mineros kóbold y los Tuneladores llenan ambos niveles; {npc:248464}, un kóbold con nombre, tiene el álbum de fotos en los túneles inferiores. {npc:248464} es élite: se recomienda ir en grupo.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "Los múrlocs de la orilla este sueltan el kelp. Desolladores: los Lobos grises del bosque recorren el bosque entre el lago y {area:91}; los Merodeadores, más al este, también dan pieles.\nCuidado: {npc:276180}, un múrloc raro de nivel 11, recorre el río junto al puente de {npc:261}, al este del bosque de los Merodeadores: no te metas con él.",
		["The vineyards and {npc:103}"] = "Los viñedos y {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "La {item:247813}, el Hacha empapada y la Caja de herramientas empapada están en el río al sur del puente. {npc:330}, una jabalina enorme, hoza en {area:62}, al oeste del río, con su {npc:390}: aparta primero a los cerditos. Mata Osos del bosque jóvenes por el camino; los Merodeadores (nivel 9-10) quedan para la vuelta con el {npc:261}, después del campamento maderero y la mina. Cuidado: {npc:248278} es un élite de nivel 11 de la orilla de los múrlocs. Ve a por su cabeza solo en grupo; si no, déjalo: es opcional.",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736} está al norte de {area:120}. Haz clic en él con cuatro manzanas rojas lustrosas en tus bolsas: se las queda y te da un {item:247824} en el acto (la misión nunca aparece en tu registro). Guarda el licor de manzana para {npc:955}: no te lo bebas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos élite: se recomienda agruparse, busca gente con quien hacerlo. {npc:248464} (élite de nivel 6) requiere un grupo de 2. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos.",
		["Walk into the mine"] = "Entra en la mina",
		["Walk through the mine"] = "Recorre la mina",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Ya que estás aquí: aprende Bastones con {npc:11867} ({object:2096}, 10 de plata); un bastón tiene más estadísticas de hechizo que un arma de una mano mientras subes de nivel.",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Empiezas delante de la abadía. {npc:823} está al pie de la escalinata; {npc:197}, dentro de la sala; {npc:951} y {npc:247229}, en la biblioteca de la derecha; {npc:196}, fuera, en la esquina noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Los Lobos jóvenes y los Lobos madereros recorren los campos junto a la abadía.",
		["grind on {npc:1922}"] = "mata {npc:1922} para subir",
		["grind on {npc:40}"] = "mata {npc:40}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "su rastreador de kóbolds muestra los kóbolds en los que hacer clic en el camino a {area:87}",
		["talk to the trainer"] = "habla con el instructor",
		["{area:18}: kill these as you meet them"] = "{area:18}: mátalos según te los encuentres",
		["{area:34}: kill these as you meet them"] = "{area:34}: mátalos según te los encuentres",
		["{area:54}: kill these as you meet them"] = "{area:54}: mátalos según te los encuentres",
		["{area:64}: kill these as you meet them"] = "{area:64}: mátalos según te los encuentres",
		["{item:247824}, from the still"] = "{item:247824}, del alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Jabalíes colmillopétreo",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} del campamento Defias",
		["{item:981}; below ground"] = "{item:981}; bajo tierra",
		["{npc:11026} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11026} la recoge cuando tu habilidad de {skill:202} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1103} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1103} la recoge cuando tu habilidad de {skill:197} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1103}, at the logging camp"] = "{npc:1103}, en el campamento maderero",
		["{npc:11068} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11068} la recoge cuando tu habilidad de {skill:333} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1215} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1215} la recoge cuando tu habilidad de {skill:171} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1215}, beside {npc:1218}"] = "{npc:1215}, junto a {npc:1218}",
		["{npc:1218} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1218} la recoge cuando tu habilidad de {skill:182} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1218}, north of {area:87}"] = "{npc:1218}, al norte de {area:87}",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está arrodillado y herido junto a un árbol en la orilla oeste de {area:18}, entre las trampas de pesca. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se marcha cuando recibe ambos y vuelve en unos 3 minutos.",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} cocina en la cocina de la posada. {npc:377} (sacerdotes), {npc:328} (magos) y {npc:917} (pícaros) están arriba en la posada: sube por la escalera de adentro, la flecha no distingue los pisos.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}: Campamento 101 te pide que la aprendas; bajo tierra",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1632} la recoge en cuanto tu habilidad de {skill:165} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, junto a {npc:6306}",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1651} la recoge en cuanto tu habilidad de {skill:356} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: domestícalo con la {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, dentro",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, el instructor de magos, dentro de la abadía",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2329} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, en la Posada Orgullo de León",
		["{npc:240}, while William brews"] = "{npc:240}, mientras William prepara la poción",
		["{npc:247226}, outside the mine"] = "{npc:247226}, fuera de la mina",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, en la biblioteca; dentro",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} y {npc:248248} están al pie de la torre.",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278} es un élite de nivel 11 en la orilla de los múrlocs, al sur del puente: se recomienda agruparse, busca gente con quien hacerlo. {quest:91740} requiere un grupo de 2. Sáltalo si vas solo: la ruta te hace recuperar la experiencia matando enemigos. Haz clic derecho en la cabeza para su misión.",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} está detrás de la Abadía, junto a los establos. {npc:198}, el instructor de magos, está arriba en la Abadía: sube por la escalera de adentro, la flecha no distingue los pisos.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, junto a la abadía",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} está con los instructores de {area:87}. Cada una de sus misiones te da una {item:15908}: úsala en la bestia que te indique y devuélvele la vara. Los Jabalíes Ocultorroca y los Osos del bosque jóvenes recorren las colinas al sur de {area:64}; los Lobos grises del bosque, el bosque al este de {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de vuelta en la posada",
		["{npc:253}, inside"] = "{npc:253}, dentro",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} en {zone:1426}; {area:87} no tiene instructor de chamanes",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, a su lado: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} vigila el puente del camino al este; {npc:248265} está justo al otro lado.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}, herbalism and alchemy back in {area:24}, tailoring at the {area:88}, mining, engineering and enchanting in {zone:1453}."] = "{npc:263399} acampa al noreste de la posada. Con una profesión aprendida, también ofrece su Campamento 101, que recoge su instructor: desuello, peletería y pesca en la orilla del lago, {skill:129} y herrería en {area:87}, herboristería y alquimia de vuelta en {area:24}, sastrería en {area:88}, minería, ingeniería y encantamiento en {zone:1453}.",
		["{npc:263399}: for {npc:11026} in {zone:1453}'s {object:28027}"] = "{npc:263399}: para {npc:11026} en {object:28027} de {zone:1453}",
		["{npc:263399}: for {npc:1103} at the {area:88}"] = "{npc:263399}: para {npc:1103} en {area:88}",
		["{npc:263399}: for {npc:11068} in {zone:1453}"] = "{npc:263399}: para {npc:11068} en {zone:1453}",
		["{npc:263399}: for {npc:1215} in {area:24}"] = "{npc:263399}: para {npc:1215} en {area:24}",
		["{npc:263399}: for {npc:1218} in {area:24}"] = "{npc:263399}: para {npc:1218} en {area:24}",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: para {npc:1632}, en la orilla del lago",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: para {npc:1651}, en la orilla del lago",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: para {npc:2329}, en la Posada Orgullo de León",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: para {npc:514}, en la herrería de {area:87}",
		["{npc:263399}: for {npc:5513} in {zone:1453}'s {object:28027}"] = "{npc:263399}: para {npc:5513} en {object:28027} de {zone:1453}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: para {npc:6306}, en la orilla del lago",
		["{npc:278}, inside"] = "{npc:278}, dentro",
		["{npc:279} in {zone:1453} takes it (the {zone:1436} guide)"] = "{npc:279} en {zone:1453} la recoge (la guía de {zone:1436})",
		["{npc:295}, inside"] = "{npc:295}, dentro",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: lo recibe {npc:5497}, en {zone:1453}",
		["{npc:375}, the priest trainer"] = "{npc:375}, la instructora de sacerdotes",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, la instructora de sacerdotes: lo recibe {npc:377}, en {area:87}",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (sacerdotes), {npc:328} (magos) y {npc:917} (pícaros) están arriba en la posada: sube por la escalera de adentro, la flecha no distingue los pisos.",
		["{npc:377}, upstairs"] = "{npc:377}, en el piso de arriba",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, en el piso de arriba: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: sana a {npc:12423} en {area:18}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: {npc:376}, en {zone:1453}, la recoge",
		["{npc:459}, outside the Abbey"] = "{npc:459}, fuera de la abadía",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} recorre {area:54}: busca dentro del círculo del mapa",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:514} la recoge en cuanto tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, en la herrería al otro lado del camino",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (the {zone:1436} guide)"] = "{npc:514}, en la herrería junto a Dughan: {npc:1416} en {zone:1453} la recoge (la guía de {zone:1436})",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: domestícalo con la {item:15908}",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} en {zone:1453}; {area:87} no tiene instructor de druidas",
		["{npc:5513} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5513} la recoge cuando tu habilidad de {skill:186} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: lo recibe {npc:6122}, en {zone:1453}",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6306} la recoge en cuanto tu habilidad de {skill:393} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6306}, inside"] = "{npc:6306}, dentro",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, en la orilla del lago al este del pueblo; dentro",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} y {npc:1651} están en la orilla de {area:18}, al este del pueblo.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: solo desolladores, las pieles se desuellan; dentro",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, junto a los establos al sur de la abadía",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} excavan en los viñedos al noreste de la abadía. De vez en cuando uno suelta un {quest:91741}: haz clic derecho en él.",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} recorre {area:34}: busca dentro del círculo del mapa",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: domestícalo con la {item:15908}",
		["{npc:823}, at the Abbey steps"] = "{npc:823}, en la escalinata de la Abadía",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de vuelta en la escalinata de la abadía",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} vende las manzanas rojas lustrosas para {quest:91736}. Las manzanas saqueadas de kóbolds y cajas también cuentan: la compra se marca sola cuando tienes cuatro.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, el instructor de guerreros; dentro",
		["{npc:915}, the rogue trainer"] = "{npc:915}, el instructor de pícaros",
		["{npc:925}, the paladin trainer"] = "{npc:925}, el instructor de paladines",
		["{npc:952}, upstairs"] = "{npc:952}, en el piso de arriba",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: quiere tu {item:247824}; dentro",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: para {npc:234} en {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} crece en los campos alrededor de los viñedos y de la granja Pedregosa; los Jabalíes colmillopétreo de alrededor dan la sangre.\nLos Jabalíes colmillopétreo pastan entre los viñedos y la granja.",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} está dentro de {area:57}, no en la colina de encima: entra por la boca y ve por la izquierda hasta el fondo de la mina; no subas las escaleras. Los Bandidos Defias de los viñedos sueltan de vez en cuando una {item:1972}: haz clic derecho en ella.\nCuidado: {npc:248464} (6), un kóbold del fondo de la mina, es élite, y {npc:79} (10, raro) recorre los túneles: atrae a los kóbolds de uno en uno.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} y {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429}: mata a estos según te los encuentres",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sentarse junto a la hoguera de {npc:265811} hasta que tengas {spell:1229451}",
		["Back at {area:256}"] = "De vuelta en {area:256}",
		["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Sal otra vez por la puerta de la ciudad y ve al este por el camino: {quest:1683} está al sur, junto a {area:736}. Llévale su cuerno a {quest:1684}.",
		["Back to the moonwell."] = "Vuelve al pozo de la luna.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Vuelve a lo alto de {area:256}. El {object:654846} está a su lado.",
		["Back to {area:442}"] = "De vuelta a {area:442}",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Vuelve arriba con {npc:3567} con las arañas hechas y el musgo de {npc:272116}.",
		["Befouled Webwoods"] = "Tejemadera infectos",
		["Below ground"] = "Bajo tierra",
		["Bloodfeather harpies"] = "Arpías Plumasangre",
		["Cast {spell:18960}"] = "Lanza {spell:18960}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; {quest:5929} está en el bosque al noroeste. Aprende la ruta de vuelo de {area:493} con {npc:10897}, al sur del lago, para viajes futuros. Después, {npc:11800} en {area:2361} lleva a los druidas directamente a {area:702} desde su diálogo: no es una ruta de vuelo que se aprenda. {npc:11802} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["Crawler Legs: the Tide Crawlers"] = "Patas de reptador: los Corremareas",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada misión de Dazalar te da una {item:15908}: úsala en la bestia que nombra y devuélvele la vara en {area:186}. Los rondadores Tejemadera merodean alrededor del poblado; los acechadores sable de la noche y los estridadores estrígidos recorren el bosque al sur.",
		["East along the road to {area:186}."] = "Al este por el camino hasta {area:186}.",
		["East from the city gate to {area:736}"] = "Al este de la puerta de la ciudad hasta {area:736}",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolta a {npc:275744} fuera del túmulo; {npc:2081} en {area:186} recibe el informe.",
		["Fandral in {zone:1457} takes it"] = "La recibe Fandral en {zone:1457}",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Los conos inferi están bajo los árboles alrededor de {area:186} y {npc:2150}: recógelos por el camino al este y entrégaselos a {npc:2150} de camino a {npc:7234}.",
		["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Solo pescadores: {npc:10216} está en el muelle. Su {item:12238} se pesca desde el propio muelle.",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Vuela de vuelta a {area:702} con {npc:3841}, dale {item:16263} a {npc:10118} en el muelle y luego vuela de vuelta a {area:442}.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Vuela otra vez a {area:702} y toma el portal hasta {npc:4217}; luego vuelve a volar a {area:442}.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Sigue el camino al suroeste desde {area:188}. {npc:2150} está sentado junto a él, justo al este de {area:186}.",
		["Follow the road west into {area:1657} and use the {item:279378} at the inn on the {area:1659} and at the tunnel mouth below {area:3425} for the last two owls. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the Moon at the south end."] = "Sigue el camino al oeste hasta {area:1657} y usa el {item:279378} en la posada de {area:1659} y en la entrada del túnel bajo {area:3425} para las dos últimas lechuzas. {npc:4241} está en {area:1659}, dentro de la ciudad. {npc:3516} está en {area:1658}, en el extremo norte de la ciudad, con {quest:922} justo al sur de él; {npc:4092}, {npc:7999}, {npc:7313} y {npc:8396} están en el Templo de la Luna, en el extremo sur.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Los emboscadores Tuercepinos se esconden a lo largo del camino al oeste de {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Los místicos Tuercepinos y {npc:7234} acampan al noreste de {area:260}. {npc:7234} suelta la {item:8049}: ábrela para conseguir la joya.\nCuidado: {npc:7234} espera junto a la hoguera con místicos a su alrededor, así que es difícil atraerlo sin que vengan otros.",
		["Gnarlpine Shamans"] = "Chamanes Tuercepinos",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vuelve a bajar a {area:702} y vuela a {area:442}. El {object:177525} está en las colinas justo al este del poblado: usa el {item:15208} allí, derrota a Lunaclaw y habla con el {npc:12144}.",
		["Grells"] = "Grells",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "Los grells (nivel 2-3) llevan {item:3297} en el bosque al oeste del árbol, junto a los tótems. Los {npc:1989} más al norte son de nivel 3-4: con los grells de los tótems basta.",
		["Heal and fortify {npc:12429}"] = "Cura y fortalece a {npc:12429}",
		["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Entra a la ciudad por la puerta. {quest:922} está justo al sur de {area:1658}, en el extremo norte, {npc:7316} al oeste, {npc:7313} y {npc:8396} en el Templo de la Luna, en el extremo sur. Al salir, usa el {item:279378} de Dalia en el banco y en la puerta de la ciudad; los otros dos búhos esperan a tu última visita.",
		["Into {area:1657}"] = "A {area:1657}",
		["Lead {quest:938} to the moonwell"] = "Lleva a {quest:938} al pozo de la luna",
		["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Aprende la ruta de vuelo con {npc:3841} donde aterrizas. El puesto de pescado de {npc:4200} está justo al norte de ella, junto a los muelles.\nEl barco atraca al oeste de la aldea. El maestro de vuelo está en la colina al sur de la posada; los que dan misiones están repartidos por la calle principal.",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Sal de {area:188} por el sendero al sureste de {area:256}: {npc:6780} está a su lado, donde baja hacia el camino a {area:186}.",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "Hechizos de nivel 12 ya que estás en el Templo de la Luna: los instructores de sacerdotes están junto a {npc:11401}.",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "Hechizos de nivel 12 ya que estás en {area:1658}: los instructores de cazadores, pícaros y druidas están todos allí.",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "Hechizos de nivel 12 ya que estás en {area:1660}: los instructores de guerreros están junto a {quest:1684}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Los sables de la Noche sarnosos y los jabalíes Cardo deambulan al norte de {area:256}, camino de la cueva. {npc:1994} está al fondo. {npc:8584} espera entre los árboles al oeste de la entrada de la cueva.",
		["Nightsabers"] = "Sables de la Noche",
		["North to {area:257}"] = "Al norte, hacia {area:257}",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "Al noreste desde la guarida de Ursal, de vuelta a {area:186}. {npc:6094} pide un {item:159} junto con las frondas y el vial: si te bebiste el tuyo, compra otro a {npc:6736} en esta posada antes de entregar.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Al noroeste de Dolanaar, camino del {area:264}, los Tejemadera infectos merodean por el bosque; {npc:272116} ronda por su borde este y lleva el {item:281023}.\n{npc:272116} es élite (nivel 12): se recomienda ir en grupo. Despeja primero las arañas a su alrededor y atráelo a él solo.",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "De vuelta al sur hacia el claro: {npc:272046} (nivel 12) vuela por las laderas al noroeste del pozo de la luna, entre Matriarcas Sangrepluma (11). Atrae primero a las arpías de su alrededor.",
		["Portal to {quest:940}"] = "Portal a {quest:940}",
		["Priest trainer"] = "Instructor de sacerdotes",
		["Sentinel Arynia again"] = "Centinela Arynia otra vez",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Al sur desde el claro hasta el camino: Shayla recorre el camino al oeste de {area:186}, desde donde lo cruza el sendero que baja del claro, al suroeste hasta la curva en torno a 38,54, y vuelta.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "Al sur de las charcas. La {object:6751} crece junto al bastión; los fúrbolgs de alrededor sueltan el resto de los colmillos.\nCuidado: los Vengadores Tuercepinos (9-10) y los Augures están muy juntos y muchos jugadores han muerto en el bastión: atráelos de uno en uno.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Al sureste de Dolanaar, hasta {npc:2080}. Los brotes azotadores deambulan a su alrededor en la orilla.",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Al suroeste desde {area:259}, pasando {area:478}: Ursal ronda el extremo sur de la isla.\nCuidado: fúrbolgs Tuercepinos de nivel 9-11 aproximadamente llenan el campamento y están muy juntos, así que es fácil atraer a varios a la vez. Acaba con ellos de uno en uno antes de enfrentarte a Ursal.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Al suroeste de Brisa Estelar, al sur de {npc:2150}. {npc:2080} cuida sus arbolitos en la orilla; los brotes azotadores y los brezomaderas deambulan a su alrededor, y los {quest:919} crecen entre ellos.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Al suroeste del túmulo. El pozo de la luna está junto a las charcas.",
		["Speak with the {quest:5929}"] = "Habla con el {quest:5929}",
		["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "Toma el antídoto de {npc:8583}, al pie de {area:256}, recién ahora, de bajada: dura cinco minutos. {npc:8584} espera al noroeste, junto a la cueva: ve directo hacia él.",
		["Take the portal down from {zone:1457} to the hippogryphs."] = "Toma el portal hacia abajo desde {zone:1457} hasta los hipogrifos.",
		["Take the portal down to the hippogryphs at {area:702}."] = "Toma el portal hacia abajo hasta los hipogrifos en {area:702}.",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Toma el portal de bajada a {area:702}. {npc:10118} está en el muelle, {npc:3838} junto a los hipogrifos. Cuando tengas {quest:6342}, vuelve a hablar con {npc:3838} y elige el vuelo a {area:442}: es gratis y aterriza junto a {npc:4200}. Si se abre el mapa de vuelo, ciérralo y vuelve a hablarle manteniendo Mayús.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Toma otra vez el camino al noroeste desde {area:186}; sigue tendida a su lado, camino de {zone:1457}.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Las arpías Plumasangre anidan en las laderas al oeste y al norte del claro. {quest:938}, una felina herida, yace junto a la pared oeste del claro, entre ellas: llévala de vuelta con la centinela Arynia, en el pozo de la luna, antes de que se acabe el tiempo.\nCuidado: las arpías están muy juntas, así que muchas veces se suman otras a la pelea. Hay lanzadoras de hechizos mezcladas entre ellas.",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "El túmulo está al sur del camino. {npc:275744} está retenida dentro, {npc:7317} duerme en lo más hondo y los cuatro cofres de reliquias están en las salas inferiores. Sus fúrbolgs sueltan los colmillos de Shayla.\nCuidado: los Defensores, Augures y Chamanes Tuercepinos (7-9) del túmulo están en grupos de tres en los túneles estrechos: atrae cada grupo hacia la entrada antes de adentrarte más.",
		["The grells west of the tree"] = "Los grells al oeste del árbol",
		["The moonwell"] = "El pozo de la luna",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "El pozo de la luna está en el centro del claro. La {object:6752} crece en su extremo norte.",
		["The moonwell sits north of {area:256}."] = "El pozo de la luna está al norte de {area:256}.",
		["The road to {zone:1457}"] = "El camino a {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "El camino al oeste hasta {area:264} pasa por {area:186}: dale la joya a {npc:3567} por el camino.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Los instructores están arriba dentro de {area:256}, a lo largo de la rampa que sube en espiral por el árbol: {npc:3593} y {npc:3594} en el primer nivel, {npc:3595} encima de ellos, {npc:3596} y {npc:3597} en la cima. La flecha no distingue los niveles.",
		["The {area:265}"] = "{area:265}",
		["The {area:478}"] = "El {area:478}",
		["The {object:177525}"] = "El {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Los {object:4406} están al fondo de {area:257}: toma el sendero central, luego a la izquierda donde se divide, hasta la cornisa alta. Los grells sueltan champiñones jacinto; los lirios alunados crecen junto a las charcas al norte de {area:256}.",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "La {object:6752} crece en el extremo norte del claro, de camino; luego al norte por el borde norte de la isla junto a {area:266}, donde acecha {npc:7319}, una araña de nivel 12.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["Upstairs"] = "Piso de arriba",
		["Use the {item:18152} at the moonwell"] = "Usa la {item:18152} en el pozo de la luna",
		["Use the {item:5185} at the moonwell"] = "Usa la {item:5185} en el pozo de la luna",
		["Use the {item:5619} at the moonwell"] = "Usa la {item:5619} en el pozo de la luna",
		["Use the {item:5621} at the moonwell"] = "Usa la {item:5621} en el pozo de la luna",
		["Walk Lynessa out and keep her alive"] = "Saca a Lynessa y mantenla con vida",
		["Warrior trainer"] = "Instructor de guerreros",
		["Webwood Lurkers"] = "Rondadores Tejemadera",
		["Webwood Spiders; below ground"] = "Arañas Tejemadera; bajo tierra",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Al oeste por el camino hacia la ciudad. Shayla recorre este tramo del camino, desde la flecha al suroeste hasta la curva en torno a 38,54, y vuelta: si no está en la flecha, sigue el camino al suroeste. Todos los fúrbolg Tuercepinos sueltan colmillos: cuentan los emboscadores de este camino, los del túmulo y los de {area:261}.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "Al oeste desde las arañas hasta {area:265}, y luego al norte a lo largo del río hasta el claro: los fustales de sus orillas sueltan los Tumores musgosos.\nCuidado: {npc:272116}, un élite de nivel 12, ronda el borde este de los Tejemadera infectos al noroeste de {area:186}: si vas solo, mantente lejos de las arañas y rodéalo.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Ya que estás aquí: aprende Bastones con {npc:11866} ({area:1660}, 10 de plata); en un cazador, el arma cuerpo a cuerpo vale sobre todo por sus estadísticas, y las de dos manos son las que más tienen.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Ya que estás aquí: aprende Bastones con {npc:11866} ({area:1660}, 10 de plata); un bastón tiene más estadísticas de hechizo que un arma de una mano mientras subes de nivel.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west, fishing and tailoring in {zone:1457}, enchanting north of the city, blacksmithing, mining and engineering in {area:442}."] = "Con una profesión aprendida, {npc:265811} también ofrece su Campamento 101, que recoge su instructor: alquimia y herboristería junto a {npc:6286}, {skill:129} con {npc:6094} en la posada, desuello y peletería en el campamento de los Tejecrines en el camino del oeste, pesca y sastrería en {zone:1457}, encantamiento al norte de la ciudad, herrería, minería e ingeniería en {area:442}.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Empiezas al pie de {area:256}, el gran árbol de {area:188}.",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "Los Sables de la noche jóvenes y los Jabalíes cardo jóvenes (nivel 1-2) deambulan alrededor de {area:256}: empieza por ellos. Los Tótems Tuercepinos están en el bosque al oeste del árbol, donde rondan los grells (2-3): ve a por ellos cuando acabes con las bestias.",
		["talk to the trainer"] = "habla con el instructor",
		["talk to {npc:3838} again: free with {quest:6342}"] = "vuelve a hablar con {npc:3838}: gratis con {quest:6342}",
		["the city gate"] = "la puerta de la ciudad",
		["the same {object:673378}: Fandral in {zone:1457} takes it"] = "la misma {object:673378}: la recibe Fandral en {zone:1457}",
		["the tunnel mouth below {area:3425}, on the way south"] = "la boca del túnel bajo {area:3425}, de camino al sur",
