		["{quest:940}: kill these as you meet them"] = "{quest:940}: mata a estos según te los encuentres",
		["{quest:97236}; below ground"] = "{quest:97236}; bajo tierra",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: lanza {spell:1259799} y Fusión de las Sombras, y luego entrégasela a {npc:3595}",
} end)()
t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north-east into the mountains to the crystal."] = "Vuelve al noreste, a las montañas, hasta el cristal.",
		["Bears and the Blackwood camp"] = "Osos y el campamento Bosquenegro",
		["Blackwood furbolgs"] = "Furbolgs Bosquenegro",
		["Boat to {area:17203}"] = "Barco a {area:17203}",
		["Class trainer"] = "Instructor de clase",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Sube a las montañas orientales al este de {area:447}; el {object:175524} está en una cornisa.",
		["Crawler Legs: the Tide Crawlers"] = "Patas de reptador: los Corremareas",
		["Druid trainer"] = "Instructor de druidas",
		["Fill the tube at the moonwell in the village"] = "Llena el tubo en el pozo de la luna del pueblo",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Sigue la costa hacia el sur, más allá de {area:447}: una {quest:4728} yace en la orilla al oeste del Páramo y otra más al sur, cerca de {area:450}. Otros tres restos yacen más al suroeste entre Oráculos Brumagris y Cazamareas Brumagris (18-20): la guía los deja para la última vuelta, cuando estés más cerca de su nivel.",
		["Grell Earrings"] = "Pendientes grell",
		["Highborne Relics"] = "Reliquias de Altonato",
		["Moonstalker Fangs"] = "Colmillos de Acechalunas",
		["Only if you still carry {quest:983}'s quest: the Tide Crawlers scuttle along the shore below the village, and {quest:983} stands on the beach just south of the docks."] = "Solo si aún llevas la misión de {quest:983}: los Corremareas corretean por la orilla bajo el pueblo, y {quest:983} está en la playa, justo al sur de los muelles.",
		["Read the {object:17188}"] = "Lee {object:17188}",
		["Read the {object:17189}"] = "Lee {object:17189}",
		["Shaman trainer"] = "Instructor de chamanes",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The beach"] = "La playa",
		["The red crystal"] = "El cristal rojo",
		["The skeletal turtle"] = "La tortuga esquelética",
		["The southern beaches"] = "Las playas del sur",
		["Thresher Eyes; underwater"] = "Ojos de trillador; bajo el agua",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Ya que estás aquí: aprende Espadas con {npc:11867} ({object:2096}, 10 de plata); una espada en la mano principal hace subir de nivel a un pícaro a buen ritmo.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:202} con {npc:11867} ({object:2096}, 10 de plata); con armas de dos manos un guerrero sube de nivel más rápido.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Te perdiste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.\nEl barco atraca al oeste del pueblo. El maestro de vuelo está en la colina al sur de la posada; los que dan misiones están repartidos por la calle principal.",
		["talk to the trainer"] = "habla con el instructor",
		["the Rabid Thistle Bears nearest {npc:3701}"] = "los osos cardo rabiosos más cercanos a {npc:3701}",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, en la playa al oeste de los muelles; bajo el agua",
		["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347}: llena el {item:12346} en {object:174795}",
		["{item:12349}, at the waterfall"] = "{item:12349}, en la cascada",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Sátiros Deth'ryll",
		["{npc:11037}, beside {npc:6300}: {quest:97941}"] = "{npc:11037}, junto a {npc:6300}: {quest:97941}",
		["{npc:2164} on the way"] = "{npc:2164} por el camino",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} en {zone:1426}; {area:87} no tiene instructor de chamanes",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} está en el borde norte de las ruinas. Altonatos malditos, Altonatos en pena y {npc:2178} las recorren; el fantasma de {npc:3667} camina entre ellos y el búho {npc:270196} vuela en círculos al este. Las dos tablillas están en las ruinas; una {quest:4722} yace en la orilla al oeste.",
		["{npc:3644}, on the pier"] = "{npc:3644}, en el muelle",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666}, en el piso de arriba de la posada",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} en {zone:1453}; {area:87} no tiene instructor de druidas",
		["{npc:6297}, beside {npc:6300}: {quest:97948}"] = "{npc:6297}, junto a {npc:6300}: {quest:97948}",
		["{zone:1453} flight master"] = "Maestro de vuelo de {zone:1453}",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["\"Badwind\" Bennic, below ground"] = "\"Malviento\" Bennic, bajo tierra",
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Usa /sentarse junto a la hoguera de {npc:263664} hasta obtener {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Los rastreatormentas y soldados de a pie Al'Aketh acampan justo al norte de {npc:257944} y sueltan la reliquia; los chilladores al oeste de ella sueltan las plumas y las garras; el {item:265105} crece junto al arroyo al oeste de ella.",
		["Back east out of the den to the grove."] = "De vuelta al este, saliendo de la guarida hacia la arboleda.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De vuelta en {quest:92529}: los clamatormentas y {npc:251662} llenan el pueblo, los clamatormentas llevan los suministros robados y {npc:251966} está en el extremo sur.",
		["Back to the Hermit"] = "Vuelve con el ermitaño",
		["Back to {area:16622}"] = "Vuelve a {area:16622}",
		["Back to {npc:252800} at the farmhouse."] = "De vuelta con {npc:252800} en la granja.",
		["Bandit Highwaymen"] = "Bandidos salteadores",
		["Below ground"] = "Bajo tierra",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon está en la sala del trono de {object:2117}, en el extremo norte de la ciudad. Luego sal por la puerta principal hacia {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Lanza {spell:1259705} sobre la línea ley",
		["Class trainer"] = "Instructor de clase",
		["Desperate times"] = "Tiempos desesperados",
		["Druid trainer"] = "Instructor de druidas",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Ábrete paso al norte hasta {area:16629}. Guardianes, clamaespíritus y maestros del acero defienden el acceso; {npc:253576} espera en la puerta del santuario, y {npc:253590}, dentro del sanctasanctórum.",
		["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "El campamento de Fillion está al noroeste, y las matriarcas chilladoras anidan justo al oeste del campamento.",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Sigue el camino al sur hasta {area:16624}. {npc:263664} acampa junto al fuego al oeste del pueblo; {npc:251523} y {npc:251903} están en el centro.",
		["For {npc:234} at {area:108}"] = "Para {npc:234} en {area:108}",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Ve al norte hacia {area:16631}. {npc:257944} acampa en su parte este.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "Ve al noroeste hasta los nidos de hipogrifo de los acantilados occidentales. El {item:263493} está alrededor de los nidos; la matriarca patrulla entre ellos.\nLos Videntes novicios practican en el claro al oeste de Shen'dar, de camino de vuelta al pueblo.",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la Guarida Colmillo Nocturno",
		["Highlands Bandits"] = "Bandidos de las Tierras Altas",
		["Innkeeper {npc:255940}, by the west gate"] = "El posadero {npc:255940}, junto a la puerta oeste",
		["Inside"] = "Dentro",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Salta desde lo alto de la atalaya y usa {spell:1259416} para bajar flotando hasta {npc:251361}, al oeste de la torre.",
		["Lariia in {zone:1438}; {area:16624} has no priest trainer"] = "Lariia en {zone:1438}; {area:16624} no tiene instructor de sacerdotes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena el {item:7207} en su base.",
		["Leave {zone:2521} to {zone:1416}"] = "Sal de {zone:2521} hacia {zone:1416}",
		["Level 14 spells while you're in {zone:1453}: warriors and rogues train in {object:2100}, hunters in the {object:28027}, mages in the Wizard's Sanctum of the {object:2101}. Druids train with {npc:5504} below."] = "Hechizos de nivel 14 ya que estás en {zone:1453}: los guerreros y pícaros entrenan en {object:2100}, los cazadores en {object:28027} y los magos en el Sagrario del Mago de {object:2101}. Los druidas entrenan con {npc:5504}, más abajo.",
		["Level 14 spells while you're with {npc:5504}."] = "Hechizos de nivel 14 ya que estás con {npc:5504}.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:257554}"] = "Escucha a {npc:257554}",
		["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "Lorthuna espera arriba en {area:16630}, al este del santuario: toma el portal a {area:16630} del sagrario interior, junto a Valennia, y cruza las alturas al este hasta {npc:252475}. Cuando caiga, {object:617084} a su lado te lleva de vuelta al pueblo.",
		["Meet {npc:253844} at the gate"] = "Reúnete con {npc:253844} en la puerta",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Al norte de las piñas: los huecos ventosos flotan alrededor del campamento de refugiados, las {item:266433} están entre las tiendas y {npc:259013} yace en su extremo norte.",
		["North-west of Valanaar along the road, past {npc:273017}: the dead cultist lies just north of him."] = "Al noroeste de Valanaar, siguiendo el camino, pasado {npc:273017}: el cultor muerto yace justo al norte de él.",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him.\nCareful: the {quest:98512} (9-10) stand close together: pull them one at a time."] = "En el camino al sureste hacia {area:16638}, {npc:273017} vigila a los {quest:98512} justo al norte de él.\nCuidado: los {quest:98512} (9-10) están muy juntos: atráelos de uno en uno.",
		["Paladin trainer"] = "Instructor de paladines",
		["Portal to {area:16630}"] = "Portal a {area:16630}",
		["Prideclaws and Galestriders"] = "Garramanadas y zancavendavales",
		["Prideclaws and Galestriders roam the grasslands around the village. Galestriders drop both the eggs and the meat: most players get the eggs from the ones just west of the village."] = "Las garramanadas y los zancavendavales rondan los pastizales alrededor del pueblo. Los zancavendavales sueltan tanto los huevos como la carne: la mayoría de jugadores consigue los huevos de los que hay justo al oeste del pueblo.",
		["Priest trainer"] = "Instructor de sacerdotes",
		["Raw Windstones and the {npc:251404}"] = "Piedras de viento en bruto y la {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Las manzanas tempestuosas maduras y los bandidos hambrientos están en el huerto junto a la granja, {quest:92683} en los campos al noreste, y los zancavendavales malhumorados por todas partes. El {npc:250929} está en el campo al noreste de la granja.",
		["Search the dead cultist"] = "Registra al cultor muerto",
		["Search the wardrobe"] = "Registra el armario",
		["Shaman trainer"] = "Instructor de chamanes",
		["Shen'dar turn-ins"] = "Entregas en Shen'dar",
		["Skyhoppers"] = "Saltanubes",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Los saltanubes pululan por los campos al oeste de {area:16638}.",
		["Speak to {npc:252448} by the inn on the west side, then cross town to {npc:252359} and {npc:259012}."] = "Habla con {npc:252448} junto a la posada del lado oeste, y luego cruza la ciudad hasta {npc:252359} y {npc:259012}.",
		["Standing our ground"] = "Nos mantenemos firmes",
		["Tame it with the {item:15908}"] = "Domestícalo con la {item:15908}",
		["Tame {npc:250874}"] = "Domestica un {npc:250874}",
		["Tame {npc:251707}"] = "Domestica un {npc:251707}",
		["Tame {npc:254588}"] = "Domestica un {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Los bandidos salteadores ocupan las colinas al norte de la granja.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp.\nCareful: the bandits stand in close groups and players often died in this camp: pull them one at a time from the edge."] = "Los Bandidos de las Tierras Altas acampan al noreste del pueblo. \"Malabrisa\" Bennic espera en el extremo norte de su campamento.\nCuidado: los bandidos están en grupos muy juntos y muchos jugadores han muerto en este campamento: atráelos de uno en uno desde el borde.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Las piedras de viento en bruto brillan en el suelo justo al sur de la arboleda. {quest:92463} revolotea sobre el prado más al este, de camino a {npc:249363}.",
		["The Ursera Scavengers den west of the grove, with {npc:251115}, the matriarch, at the back of the den; {npc:250926} prowl the woods between the den and the grove."] = "Los carroñeros ursera tienen su guarida al oeste de la arboleda, con {npc:251115}, la matriarca, al fondo; {npc:250926} merodean por el bosque entre la guarida y la arboleda.",
		["The Windstone Formations"] = "Las formaciones de piedras de viento",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Las formaciones de piedras de viento están en la loma al oeste del campamento de Fillion.",
		["The bounty board"] = "El tablón de recompensas",
		["The class trainers stand together in the grove"] = "Los instructores de clase están juntos en la arboleda",
		["The dead cultist"] = "El cultor muerto",
		["The eastern watchtower"] = "La atalaya oriental",
		["The missing scholar"] = "El erudito desaparecido",
		["The road to {area:16638}"] = "El camino a {area:16638}",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "La {item:254871}",
		["The {object:581822}"] = "La {object:581822}",
		["The {object:581822} lies by the path west of {area:16638}."] = "{object:581822} está junto al sendero al oeste de {area:16638}.",
		["The {object:617084} sets you down beside {npc:252475} at the south end of the town. {npc:252476} is at the north end, {npc:259012} a few steps north-west of her."] = "{object:617084} te deja junto a {npc:252475}, en el extremo sur del pueblo. {npc:252476} está en el extremo norte, {npc:259012} a pocos pasos al noroeste de ella.",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Piso de arriba",
		["Valennia asks you to hear out both leaders: {npc:252475} of the Alliance and {npc:251968} of the Horde. {npc:251968}'s name shows red to you, but she talks to you all the same, and the quest needs both."] = "Valennia te pide que escuches a ambos líderes: {npc:252475} de la Alianza y {npc:251968} de la Horda. El nombre de {npc:251968} aparece en rojo, pero habla contigo igualmente, y la misión necesita a ambos.",
		["Village quests"] = "Misiones del pueblo",
		["Warlock trainer"] = "Instructor de brujos",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Ya que estás aquí: aprende Bastones con {npc:11867} ({object:2096}, 10 de plata); en un cazador, el arma cuerpo a cuerpo vale sobre todo por sus estadísticas, y las de dos manos son las que más tienen.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Ya que estás aquí: aprende Espadas con {npc:11867} ({object:2096}, 10 de plata); una espada en la mano principal hace subir de nivel a un pícaro a buen ritmo.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:202} con {npc:11867} ({object:2096}, 10 de plata); con armas de dos manos un guerrero sube de nivel más rápido.",
		["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round. {quest:93159} has his own for engineers."] = "Con una profesión aprendida, {npc:263664} también ofrece su Campamento 101, que su instructor de {area:16624} recoge en la vuelta del poblado. {quest:93159} tiene el suyo para ingenieros.",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Te despiertas en {area:16622}. {npc:251362} está a tu lado; {npc:251361} está a unos pasos al oeste, y {npc:251368}, junto al borde sur de la arboleda.",
		["talk to the {npc:251684}"] = "habla con {npc:251684}",
		["{area:16622} turn-ins"] = "Entregas en {area:16622}",
		["{area:16622}: kill these as you meet them"] = "{area:16622}: mátalos según te los encuentres",
		["{area:16623}: kill these as you meet them"] = "{area:16623}: mátalos según te los encuentres",
		["{area:16624} again"] = "De nuevo {area:16624}",
		["{area:16626}: kill these as you meet them"] = "{area:16626}: mátalos según te los encuentres",
		["{area:16631}: kill these as you meet them"] = "{area:16631}: mátalos según te los encuentres",
		["{area:16638} turn-ins"] = "Entregas en {area:16638}",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, el destino de Zephras",
		["{area:16638}, the turncoat"] = "{area:16638}, el traidor",
		["{area:16833}: kill these as you meet them"] = "{area:16833}: mátalos según te los encuentres",
		["{item:252665}; below ground"] = "{item:252665}; bajo tierra",
		["{item:257107}; below ground"] = "{item:257107}; bajo tierra",
		["{item:258771}: the Stormchasers and Footsoldiers around {npc:254151}'s camp"] = "{item:258771}: los cazatormentas y los soldados alrededor del campamento de {npc:254151}",
		["{item:262668}: by the formations"] = "{item:262668}: junto a las formaciones",
		["{item:263993}: {npc:257196} holds it, west of the shrine's approach; defeat him for it on the way in"] = "{item:263993}: la tiene {npc:257196}, al oeste del acceso al santuario; derrótalo para conseguirla al entrar",
		["{npc:1646} stands in {object:2098}, on the way from the Keep to the main gate: his compass is in his old house in {zone:1436}, on the way."] = "{npc:1646} está en {object:2098}, en el camino del Castillo a la puerta principal: su brújula está en su vieja casa de {zone:1436}, en el camino.",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} vigila al este de la arboleda. Los {npc:251143} y los convertidos Al'Aketh ({npc:251160}) se reúnen justo al norte de ella; la línea ley se alza más al norte: lanza sobre ella tu habilidad racial {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} y moscas de cirro molestas rondan el prado justo al sureste de la arboleda.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: una nota de tu instructor",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: lee la {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: la {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, el instructor de druidas, en la planta baja del árbol detrás de {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, la instructora de magos: lee primero el {item:282416}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, en la atalaya",
		["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905}: Campamento 101 te pide que la aprendas",
		["{npc:251913} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251913} la recoge en cuanto tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:251913}, beside {npc:251991}"] = "{npc:251913}, junto a {npc:251991}",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, en la atalaya",
		["{npc:251991} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251991} la recoge en cuanto tu habilidad de {skill:197} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:251992} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251992} la recoge en cuanto tu habilidad de {skill:356} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:251992}, on the south edge of the village"] = "{npc:251992}, en el borde sur del pueblo",
		["{npc:251993} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:251993} la recoge en cuanto tu habilidad de {skill:165} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:252095} camps south-west of the grove, south of the Ursera den, on the way south to Shen'dar. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} acampa al suroeste de la arboleda, al sur de la guarida ursera, de camino al sur hacia Shen'dar. Los matones Al'Aketh ocupan el campamento al suroeste de ella; {npc:256935} está en el medio.\nCuidado: {npc:256935} lanza descargas; apártalo de los demás sectarios antes de pelear para que no se sumen.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} defiende la torre occidental, al suroeste de Falaath. {npc:256966} y los guardias caídos yacen justo al sur de ella.",
		["{npc:252359}, between the west gate and Valennia's house: {quest:94006}"] = "{npc:252359}, entre la puerta oeste y la casa de Valennia: {quest:94006}",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, el instructor de magos",
		["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}, junto a {npc:257006}: {npc:257196} defiende el Baluarte en {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} defiende la atalaya al norte de {area:16638}. El campamento Al'Aketh está justo al oeste de la torre, con sus sanadores hacia 65,68 y 65,65; {npc:252666} está en su extremo norte. Los Al'Aketh de allí sueltan Windstone Charms.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} y {npc:252476} están en el extremo norte de {area:16638}; {npc:252475} y {npc:253204}, en el extremo sur.",
		["{npc:252383}, upstairs"] = "{npc:252383}, en el piso de arriba",
		["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} recupera la primera {item:15908} y te da dos más, de a una: los Zancavendavales malhumorados y los alfas Vuldren recorren los campos justo al norte de ella. Doma a cada uno con su vara y devuélvele la vara. {npc:254411}, a su lado, enseña {spell:5149}.",
		["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "{npc:252389}, junto a {npc:257006}: la primera {item:15908}",
		["{npc:252475} sends you on to {area:279}. Take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475} te manda a {area:279}. Toma el surcacielos desde la torre del muelle justo al sur de {area:16638}: aterriza junto al campamento del Kirin Tor al oeste de {area:279}, al lado de {npc:259084} y el portal de los cielonatos.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} espera junto al portal de los cielonatos",
		["{npc:252476}, upstairs"] = "{npc:252476}, en el piso de arriba",
		["{npc:252800} again"] = "De nuevo {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} lleva la granja de las tierras bajas del suroeste.",
		["{npc:252800}, at the farmhouse"] = "{npc:252800}, en la granja",
		["{npc:253590}, in the sanctum; upstairs"] = "{npc:253590}, en el sanctasanctórum; en el piso de arriba",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:254151}, {npc:258130} y {npc:258134} están al noreste de {npc:257944}; {npc:253622} está al este de ellos. Haalien también suelta una {quest:94490}. Para {quest:94489}, entra en la Guarida Colmillo Nocturno, sana a 7 druidas heridos y encuentra a {npc:258130}.",
		["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "{npc:254588}, entre los cangrejos: doma uno con la primera {item:15908} de {npc:252389} mientras estás ahí",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} acecha en las colinas al suroeste del pueblo, de camino de vuelta. {npc:254589} es élite: conviene ir en grupo.",
		["{npc:255853} waits by the falls just north of the watchtower. {npc:258443} prowls the {area:16623} south-west of the dead cultist, where you go after {area:16638}."] = "{npc:255853} espera junto a las cascadas justo al norte de la atalaya. {npc:258443} merodea por {area:16623} al suroeste del cultor muerto, adonde vas después de {area:16638}.",
		["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853}, junto a las cascadas al noreste de {area:16638}, de camino al norte: {spell:5487}",
		["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "{npc:257006} y {npc:252448} están en el lado oeste de {area:16638}, junto a la posada; {npc:252377} y {npc:252389} entrenan justo al oeste de {npc:257006}. Los reptadores Canzalvaje cubren la orilla más al oeste, cerca de 51,70.",
		["{npc:257006}, inside"] = "{npc:257006}, dentro",
		["{npc:257018} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257018} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:257018}, at the south side of the village"] = "{npc:257018}, en el lado sur del pueblo",
		["{npc:257019} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:257019} la recoge en cuanto tu habilidad de {skill:171} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
