		["Leave {zone:1426} east through the South Gate tunnel; it opens into {zone:1432} by the dwarf king statues of the {area:924}."] = "Sal de {zone:1426} hacia el este por el túnel de la Puerta Sur; da a {zone:1432} junto a las estatuas de los reyes enanos de {area:924}.",
		["Silverpine's road north leads into {zone:1420}. {area:159}, {area:154} and the {zone:1458} ruins are Horde ground."] = "El camino hacia el norte del Bosque de Argénteos lleva a {zone:1420}. {area:159}, {area:154} y las ruinas de {zone:1458} son territorio de la Horda.",
		["Take the boat from {area:150} to {area:271}."] = "Toma el barco de {area:150} a {area:271}.",
		["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}, then leave the city through its gates."] = "Toma el {area:2257} desde {object:28027} de {zone:1453} hasta {zone:1455} y sal de la ciudad por sus puertas.",
		["The {area:836} pass in south-eastern {zone:1437} leads down into {zone:1432} by {area:925}."] = "El paso de {area:836}, en el sureste de {zone:1437}, baja hasta {zone:1432} junto a {area:925}.",
		["Walk east from {area:287} into the {zone:1417} (level 30+ creatures off the road), south to the {area:881} bridge, and across it into the {zone:1437}. {area:150} is an Alliance town."] = "Ve hacia el este desde {area:287} hasta {zone:1417} (criaturas de nivel 30+ fuera del camino), al sur hasta el puente de {area:881}, y crúzalo hacia {zone:1437}. {area:150} es un pueblo de la Alianza.",
		["any one of these names counts"] = "vale cualquiera de estos nombres",
		["the discovery triggers at the {area:1038}: do not go into {area:1037} itself"] = "el descubrimiento se activa en {area:1038}: no entres en {area:1037}",
		["{area:154} opens onto {zone:1420}; {area:159} is east along the road. Orcs, trolls and tauren arrive at the zeppelin tower by the {zone:1458}."] = "{area:154} da a {zone:1420}; {area:159} está al este, siguiendo el camino. Orcos, trols y tauren llegan a la torre del zepelín junto a {zone:1458}.",
		["{area:9} opens onto {zone:1429}; {area:87} is south down the road."] = "{area:9} da a {zone:1429}; {area:87} está al sur, siguiendo el camino.",
		["{zone:1421} is south of {zone:1420}: follow the road south from {area:159}."] = "{zone:1421} está al sur de {zone:1420}: sigue el camino hacia el sur desde {area:159}.",
		["{zone:1429} is north of {zone:1436} and {zone:1431}. {area:87}, {area:9} and {zone:1453}'s gates are Alliance ground with guards."] = "{zone:1429} está al norte de {zone:1436} y {zone:1431}. {area:87}, {area:9} y las puertas de {zone:1453} son territorio de la Alianza con guardias.",
		["{zone:1436} borders {zone:1431} to the west. {area:108} is an Alliance town."] = "{zone:1436} linda al oeste con {zone:1431}. {area:108} es un pueblo de la Alianza.",
} end)()
