		["{area:392} flight master"] = "Maestro de vuelo de {area:392}",
		["{area:392} for the Felsteed"] = "{area:392}, por el Corcel vil",
		["{area:75} flight master"] = "Maestro de vuelo de {area:75}",
		["{area:976} flight master"] = "Maestro de vuelo de {area:976}",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} es el pueblo goblin amurallado justo pasada la frontera de {zone:1446}.",
		["{area:985}: kill these as you meet them"] = "{area:985}: mátalos según te los encuentres",
		["{npc:2486}, beside the inn: {quest:348}"] = "{npc:2486}, junto a la posada: {quest:348}",
		["{npc:2498}, inside"] = "{npc:2498}, dentro",
		["{npc:2519}: the basilisks bask beside the road south, on the ride to {area:35}"] = "{npc:2519}: los basiliscos toman el sol junto al camino del sur, de camino a {area:35}",
		["{npc:260405}, on the pier: Friz's errand from the {zone:2548}, if you carry it"] = "{npc:260405}, en el muelle: el encargo de Friz de {zone:2548}, si lo llevas",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}, de camino de vuelta a Zinge",
		["{npc:3690}, riding trainer"] = "{npc:3690}, instructor de equitación",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}: {quest:1137}, de parte de Martek en {zone:1418}",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4706}, junto a {npc:4630}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, instructor de equitación",
		["{npc:4773}, riding trainer"] = "{npc:4773}, instructora de equitación",
		["{npc:5234} walks around {area:2522}: look inside the circle on the map"] = "{npc:5234} da vueltas por {area:2522}: búscalo dentro del círculo del mapa",
		["{npc:5591}, inside"] = "{npc:5591}, dentro",
		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} da vueltas por aquí: búscalo dentro del círculo del mapa",
		["{npc:737}, upstairs"] = "{npc:737}, en el piso de arriba",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}, later in this guide"] = "{npc:773}, arriba: para {quest:2864} en {area:976}, más adelante en esta guía",
		["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} da vueltas por {area:1099}: búscalo dentro del círculo del mapa",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
		["{npc:7854}, inside"] = "{npc:7854}, dentro",
		["{npc:7875}: for {npc:7010} in {zone:1454}"] = "{npc:7875}: para {npc:7010} en {zone:1454}",
		["{npc:7881}, inside"] = "{npc:7881}, dentro",
		["{npc:7882}, inside"] = "{npc:7882}, dentro",
		["{npc:7953}, riding trainer"] = "{npc:7953}, instructor de equitación",
		["{npc:8115}: {npc:263190}'s errand from the {zone:2548}, if you carry it"] = "{npc:8115}: el encargo de {npc:263190} de {zone:2548}, si lo llevas",
		["{object:3202} flight master"] = "Maestro de vuelo de {object:3202}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: dentro de una hora",
		["{zone:1434} and {area:75} first, then {zone:1446} and {zone:1444}."] = "Primero {zone:1434} y {area:75}, luego {zone:1446} y {zone:1444}.",
		["{zone:1444}: kill these as you meet them"] = "{zone:1444}: mata a estos según te los encuentres",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
		["{zone:1456} flight master"] = "Maestro de vuelo de {zone:1456}",
		["{zone:2652} is next, a ride north from {area:1099} into {zone:1443}: keep your {zone:1454} hand-ins (Neeru, Zilzibin, {npc:4485}, {npc:7311}) for the flight there after it."] = "{zone:2652} es lo siguiente, cabalgando al norte desde {area:1099} hasta {zone:1443}: guarda tus entregas de {zone:1454} (Neeru, Zilzibin, {npc:4485}, {npc:7311}) para el vuelo hasta allí después.",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back to Mudsprocket before you ride north."] = "Vuelve a Barroñuela antes de cabalgar al norte.",
		["Below ground"] = "Bajo tierra",
		["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps. The {item:280092} grows in the bog just east of Mudsprocket."] = "Al este por {area:511}: los exploradores Crin de Fuego y colas de ceniza recorren su borde norte con las crías y dragonantes abrasadores; los rompescamas guardan las cuevas de dragones más al sureste. El rapé, el grog y la caja fuerte de Mok'Morokk están en los campamentos de dracónidos. {item:280092} crece en la ciénaga justo al este de Barroñuela.",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:496}"] = "Vuela a {area:496}",
		["From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Desde el maestro de vuelo: el {object:172960}, luego la Calle Mayor y después el {object:172958}.",
		["Inside {area:498}"] = "Dentro de {area:498}",
		["Level 45.37"] = "Nivel 45.37",
		["Mudsprocket"] = "Barroñuela",
		["Onyxia's eggs"] = "Huevos de Onyxia",
		["Ride back north to Brackenwall."] = "Vuelve cabalgando al norte, a Murohelecho.",
		["Skips {zone:2652}: about a dozen fewer quests, a third of a level lower into {zone:1446}"] = "Se salta {zone:2652}: una docena de misiones menos, un tercio de nivel más bajo al llegar a {zone:1446}",
		["South-east from the {object:2555} to Mudsprocket, the goblin camp at the {area:511}'s western edge: {npc:270723} and {npc:270727} stand together in the camp. Their whelps, scales and {item:280092} come on the same {area:511} loop as Brackenwall's quests."] = "Al sureste desde {object:2555} hasta Barroñuela, el campamento goblin en el borde oeste de {area:511}: {npc:270723} y {npc:270727} están juntos en el campamento. Sus dragonantes, escamas y {item:280092} vienen en la misma vuelta por {area:511} que las misiones de Murohelecho.",
		["Stays on the main route"] = "Sigue en la ruta principal",
		["Takes you to level 47"] = "Te lleva al nivel 47",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Los Huevos de Onyxia están en las cuevas de dragones del sureste de {area:511}, guardados por los Horrocrustos; destroza cinco.",
		["The {object:2555}"] = "{object:2555}",
		["The {object:2555} lies to the south-west."] = "{object:2555} está al suroeste.",
		["Then on to {zone:1446}"] = "Después, a {zone:1446}",
		["grind on {npc:4329}"] = "mata {npc:4329}",
		["the {object:2555}"] = "{object:2555}",
		["{area:1099} flight master"] = "Maestro de vuelo de {area:1099}",
		["{area:510}: kill these as you meet them"] = "{area:510}: mátalos según te los encuentres",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "El desafío de {npc:4500}, de vuelta en Murohelecho, requiere un grupo de tres. Si vas solo, mata Exploradores Pirocabello aquí, en el borde norte de {area:511}, hasta el nivel 45.37 antes de volver cabalgando al norte, para no tener que bajar otra vez a por ello. O bien, con un grupo, haz en su lugar la mazmorra de {area:978}.",
		["{npc:4501}, below ground"] = "{npc:4501}, bajo tierra",
		["{npc:6986}, the Drag"] = "{npc:6986}, La Calle Mayor",
		["{npc:7010}, the Drag"] = "{npc:7010}, La Calada",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
		["{zone:1454}'s hand-ins, {area:1099}'s Muisek vessel, then Dustwallow's {area:511} and {area:496}."] = "Las entregas de {zone:1454}, la vasija muisek de {area:1099} y luego {area:511} y {area:496} en el Marjal Revolcafango.",
		["{zone:1456} flight master"] = "Maestro de vuelo de {zone:1456}",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "De vuelta al este, con Fizzledowser, en el lado oeste de {area:976}; {npc:7771} está al sur desde ahí.",
		["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each. No power source in your bags, or its two hours ran out? Abandon {quest:654} if it is in your log, then take Another Power Source? from {npc:7407}: he gives a new one for ten more Wastewander Water Pouches, from the Wastewander camps east of {area:976}."] = "De vuelta al norte, justo al sur de {area:976}, usa {item:8524} ahora: empieza el temporizador de dos horas. Las hienas Zarpampolla ({npc:5426}), los basiliscos Pielvidrio ({npc:5419}) y los cazadores escórpidos ({npc:5422}) comparten las dunas de aquí. Cada uno puede soltar una muestra sin probar: úsala y o pasa como aceptable o se pierde. Sigue matando hasta tener ocho de cada. ¿Sin fuente de energía en las bolsas, o se acabaron sus dos horas? Abandona {quest:654} si está en tu registro y luego acepta ¿Otra fuente de energía? de {npc:7407}: te da una nueva por diez odres de agua Deambuladores más, de los campamentos Deambuladores al este de {area:976}.",
		["Below ground"] = "Bajo tierra",
		["Below ground: the plans, on the {area:1443}'s upper ledge"] = "Bajo tierra: los planos, en la cornisa superior de {area:1443}",
		["Boat to {area:16727}"] = "Barco a {area:16727}",
		["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Cuidado: los hechiceros de las sombras (nivel 42-43) invocan a un abisario fuera de combate y atacan con Inmolar y {spell:686}. Los pícaros pueden desarmarte, los rufianes se mueven en Sigilo, y los asesinos usan Ejecutar cuando estás al 20% de vida o menos.",
		["Dark Iron Lookouts"] = "Vigías Hierro Negro",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["For your {area:978} run, after {area:979}: {npc:7407}, by the water tower, wants his {quest:2768} back; {quest:2864} his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."] = "Para tu incursión en {area:978}, después de {area:979}: {npc:7407}, junto a la torre de agua, quiere que le devuelvas su {quest:2768}; {quest:2864}, sus caparazones de escarabajo, y Trenton Lighthammer, Temple de trol, si aún no las has aceptado.",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Más al sur, el equipo del aperador junior Scrimshank está en la entrada de una colmena Centipaar.\nCuidado: un bicho guarda el equipo. Muchos bichos patrullan los túneles, algunos de nivel 50, así que las peleas a menudo arrastran refuerzos extra.",
		["Heavy War Golems patrol the Cauldron below {npc:8479} and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\n{area:1443} opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."] = "Los Gólems de guerra pesados patrullan La Caldera bajo {npc:8479} y sueltan el aceite; los Elementales de magma y los Elementales llameantes que vagan entre ellos sueltan los corazones. Los Capataces y Esclavistas Hierro Negro arrean a los esclavos por los caminos; un Esclavista puede soltar la {item:11818}: guárdala.\nLas Lavarañas superiores recorren las mesetas y las charcas de lava del suroeste de la garganta.\n{area:1443} se abre al norte de La Caldera. Los Incendosaurios nadan en sus charcas de lava: atráelos al borde. Los planos secretos están en la cornisa superior del foso.\nCuidado: los Esclavistas Hierro Negro (nivel 45-46) piden ayuda a aliados a menos de 15 m al atraerlos, lanzan Red desde hasta 15 m y usan Desgarrar cuerpo a cuerpo. Los Incendosaurios y Lavarañas más grandes son de nivel 49: atráelos de uno en uno.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Su siguiente encargo pide el {item:10552} de fieles élite: déjalo.",
		["Into {zone:1427}"] = "Hacia {zone:1427}",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "Guarda la Fuente de energía modelo 4711-FTZ que te dio Bilgewhizzle: inicia {quest:654}, con un temporizador de dos horas, así que úsala al volver al norte desde la colmena de Patagolpe.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "Solo con el localizador de emergencia: OOX-17/TN está al sureste de la colmena de Patagolpe. Escóltalo al norte hasta {area:977}; su recompensa te espera con Oglethorpe Obnoticus en {area:35}.\nCuidado: la escolta tiene dos emboscadas. Tres escórpidos de nivel 47 atacan cerca del inicio. Cerca del final, junto a la playa, atacan tres humanos Vagayermo: un mago y dos asesinos, de nivel 44 más o menos.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Solo con la {item:11818}: vuelve al este hasta el {object:173265} de la excavación.",
		["Ride back north to {area:1446}, just past {npc:8479}."] = "Cabalga de vuelta al norte hasta {area:1446}, justo pasado {npc:8479}.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Cabalga al noroeste cruzando la garganta; {area:1446} es el campamento con andamios del noroeste.",
		["Ride south from {area:1446} into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below {npc:8479}. Careful: the biggest golems are 49: pull them one at a time."] = "Cabalga al sur desde {area:1446} hacia La Caldera: los Capataces y Esclavistas Hierro Negro arrean a los esclavos por los caminos, y los Gólems de guerra pesados patrullan el fondo bajo {npc:8479}. Cuidado: los gólems más grandes son de nivel 49: atráelos de uno en uno.",
		["Scrimshank's gear"] = "Equipo de análisis de Patagolpe",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Los Vigías Hierro Negro vigilan las crestas alrededor de las torres de guardia al sur de La Caldera; uno de cada diez, más o menos, lleva el {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Los Vapoherreros Hierro Negro trabajan en los hornos del centro de La Caldera; la mitad lleva una {item:10551} y uno de cada diez la {item:18959}. Los esclavos, Esclavistas y Capataces también llevan dagas.",
		["The Steamsmiths' furnaces"] = "Los hornos de los Vapoherreros",
		["The flight lands beside {npc:7876}. Take the town's quests before riding west to {area:979}."] = "El vuelo aterriza junto a {npc:7876}. Toma las misiones del pueblo antes de cabalgar al oeste hasta {area:979}.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: {npc:7407}, junto a la torre de agua.",
		["The {quest:3042}: {npc:7804}, a short walk from the flight master."] = "{quest:3042}: {npc:7804}, a poca distancia del maestro de vuelo.",
		["Use the {item:8524}"] = "Usa la {item:8524}",
		["Walk {npc:5955} all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "Acompaña a {npc:5955} todo el camino hasta su esposa {npc:6015} en {area:977}, al noreste cruzando el desierto: quédate cerca, ve despacio por él y rechaza lo que le ataque. No montes ni uses la piedra de hogar fuera de su alcance. {npc:8579} también está en el puerto.",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Ve al oeste por el camino del sur; {npc:7771} acampa junto a las ruinas de {area:1938}. Ponte su {item:9978}: muestra los adornos enterrados, aquí y alrededor de {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Al oeste de Gadgetzan, usa la {item:8584} junto a la charca del campamento trol.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."] = "Al oeste, los insectos Centipaar pululan alrededor de sus colmenas; cualquiera suelta las piezas.\nCuidado: los Enjambristas Centipaar lanzan {npc:4196} dentro y fuera de combate, lo que atrae pequeños añadidos que te interrumpen. Los Atracadunas son de nivel 49-50: ve a por los Obreros y los Tuneleros.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Te perdiste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.",
		["Your {area:978} scarab shells: {npc:7876}, beside the wind rider master."] = "Tus caparazones de escarabajo de {area:978}: {npc:7876}, junto al maestro de jinetes del viento.",
		["for {npc:5204} in the {zone:1458}, around level 52"] = "para {npc:5204} en {zone:1458}, sobre el nivel 52",
		["for {npc:7010} in {zone:1454}, around level 50"] = "para {npc:7010} en {zone:1454}, hacia el nivel 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "el {item:8526} crece en {zone:1425}, hacia el nivel 48",
		["the {object:173265}"] = "el {object:173265}",
		["{area:246}'s slavers and golems"] = "los esclavistas y gólems de {area:246}",
		["{area:496} flight master"] = "Maestro de vuelo de {area:496}",
		["{area:976} and the {zone:1427} at 47-49: the Wastewander camps, {npc:5955}'s escort and {area:1446}."] = "{area:976} y {zone:1427} a nivel 47-49: los campamentos Wastewander, la escolta de {npc:5955} y {area:1446}.",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} es una mazmorra para un grupo de cinco; sus misiones de aquí son de nivel 45 a 47. Su puerta está a unos 400 metros al norte de la charca del campamento trol.\nDentro: los Escarabajos sueltan los caparazones, cualquier trol Furiarena puede soltar {quest:3042} y {npc:7604} lleva {quest:2768}.",
		["{item:11818}, a rare drop"] = "{item:11818}, botín poco común",
		["{item:8623}, a rare drop"] = "{item:8623}, botín poco común",
		["{npc:5594}, inside"] = "{npc:5594}, dentro",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:5955}, a little turtle, wanders the west edge of the {quest:3362} between several spots: the arrow goes from one to the next until you find him. Leave the Thistleshrubs (48-50) alone."] = "{npc:5955}, una tortuguita, deambula por el borde oeste de {quest:3362} entre varios puntos: la flecha va de uno a otro hasta que la encuentres. Deja en paz a los Cardos (48-50).",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
		["{npc:8479} stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "{npc:8479} está solo al sur de {area:1446}, al borde de La Caldera. Escucha su historia.",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, dentro",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: los Escarabajos, dentro",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: los trols Furiarena, dentro",
		["{quest:3161} ornaments"] = "Adornos de {quest:3161}",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362}: mata estos al encontrarlos",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427}: mata a estos según te los encuentres",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Vuelve al oeste a {area:350}; los forestales y tiradores están cerca del refugio, y los exploradores y avanzadas, en las laderas al sur.",
		["East of the village, the violet flower grows in the hills."] = "Al este del poblado, la flor violeta crece en las colinas.",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Fly to {area:75}"] = "Vuela a {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Sigue los caminos hacia el este a través de {zone:1425} hasta el poblado trol de la costa este.",
		["Highvale"] = "Vallealto",
		["His next request, going on to the {area:355}, is for a group."] = "Su siguiente encargo, que continúa en {area:355}, es para grupo.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. The trolls inside are elite: stay with your group and keep to the paths."] = "La calavera del cazador Malkhor está en un montón bajo las ruinas Vilrama, y sus huesos, en otro montón al pie de {area:354}. Las vasijas de sangre contaminada están en las terrazas inferiores, y {npc:14757} está preso en la cima. Los trols de dentro son élite: no te separes de tu grupo y no te salgas de los senderos.",
		["No flight path to {area:75} yet: the arrow takes the quickest way there (by the {object:3202} flight and the road through {zone:1431} and {zone:1430}). Learn {area:75}'s flight path when you arrive."] = "Aún no tienes la ruta de vuelo a {area:75}: la flecha toma el camino más rápido (con el vuelo a {object:3202} y el camino por {zone:1431} y {zone:1430}). Aprende la ruta de vuelo de {area:75} al llegar.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Al norte por la costa, la cesta de merienda de {npc:14731} está en el islote; la vigila un {npc:14748}.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the top floor"] = "En el piso superior",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Ve hasta el extremo oeste, a {area:348}, la ciudad de los Martillo Salvaje, y deja el mensaje junto al pozo del centro. La ciudad está llena de guardias de la Alianza: entra, déjalo y sal.",
		["Ride back north to the bloodmages."] = "Vuelve al norte con los magos sangrientos.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Ve al noreste desde {area:272} hasta {zone:1425} y sigue el camino hacia el este; {npc:7801} acampa en la colina al sur de {area:350} de los elfos.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Sal de {area:75} hacia el oeste y ve al sur por el cañón hasta {zone:1419}; los dos magos sangrientos están junto al camino, nada más entrar.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Al sur del refugio, los trols Secacorteza ocupan sus poblados. Todos llevan un cráneo: con veinte, usa {item:15002} para hacer el Pico cargado de Nimboya y clávalo dentro del poblado.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "De nuevo al suroeste, el exiliado se esconde junto a las ruinas de {area:353}.",
		["South-west of the lake, the Vilebranch soothsayers hold the {area:355}, the troll temple south of the central hills. Qiaga and {npc:8636} (elite, 50) stand at its top: take the soothsayers on the lower steps.\nSouth-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Al suroeste del lago, los adivinos Vilrama ocupan {area:355}, el templo trol al sur de las colinas centrales. Qiaga y {npc:8636} (élite, 50) están en la cima: mata a los adivinos de los escalones inferiores.\nAl suroeste, los Aulladores Crinpladas recorren las colinas al este de los poblados Secacorteza.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "Los elfos de Vallealto acampan alrededor de {area:350}. Quema el informe, las notas y los archivos de sus campamentos. {npc:7780} está preso dentro del refugio: sácalo de allí y rechaza la emboscada por el camino.\nCuidado: grupos de unos tres elfos emboscan la escolta, normalmente dos veces.",
		["The big turtles crawl along the beaches north of the village, and {npc:2491}'s bottles of port lie on the same beaches, from the village up to the {area:307}: pick them up as you go. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.\nCareful: the biggest Saltwater Snapjaws are 50: pull them one at a time."] = "Las tortugas grandes se arrastran por las playas al norte del poblado, y las botellas de oporto de {npc:2491} están en las mismas playas, desde el poblado hasta {area:307}: recógelas sobre la marcha. Un quijaforte puede soltar, rara vez, la baliza de socorro de OOX-09/HL: guárdala.\nCuidado: los Quijafortes Aguasalada más grandes son de nivel 50: atráelos de uno en uno.",
		["The bloodmages"] = "Los magos sangrientos",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Las cajas de {item:8684} están alrededor del campamento abandonado de la Horda en {area:351}, entre los mocos.",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use {spell:5416}; {npc:8301} adds Knockdown. Pull the Stingers one at a time."] = "Las cinco misiones piden las mismas partes: reúnelas todas de una pasada. Al oeste del camino, los buitres {npc:5982}, las Hienas risitas hambrientas, los Aguijoneros Scorpok y los basiliscos Ojo de la Muerte comparten las colinas.\nAl este del camino, los jabalíes Crin de Ceniza y los Gruñidores hozan en las laderas junto a los basiliscos Piedrarroja. Aléjate de los Jabalíes infernales de nivel 52, más al sur.\nCuidado: los Aguijoneros Scorpok (50-51) usan {spell:5416}; {npc:8301} añade Derribo. Atrae a los Aguijoneros de uno en uno.",
		["The secret lies on the {area:307}, above the beach."] = "El secreto está en {area:307}, sobre la playa.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Sus misiones siguientes piden otra vez las mismas partes a cambio de un objeto de mejora y no dan experiencia: déjalas.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Son enemigos élite: se recomienda ir en grupo, busca a gente con quien hacerlo. {npc:7977} es élite de nivel 48: la mayoría de las clases puede con ella en solitario a nivel 50, pero quizá necesites ayuda. Sáltatela si vas solo: la ruta te hace recuperar la experiencia matando.\n{npc:7977} recorre la orilla bajo {area:307}, desde la flecha hacia el sur hasta 75,66 aprox. y hacia el norte hasta 82,52 aprox.: si no está en la flecha, sigue la orilla.",
		["To {area:75}"] = "A {area:75}",
		["Underwater"] = "Bajo el agua",
		["for {npc:6986} in {zone:1454}, around level 50"] = "para {npc:6986} en {zone:1454}, hacia el nivel 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "para {npc:7825} en {zone:1458}, hacia el nivel 50",
		["grind on {npc:2505}"] = "mata {npc:2505}",
		["{area:1440}: kill these as you meet them"] = "{area:1440}: mátalos según te los encuentres",
		["{area:1917}: kill these as you meet them"] = "{area:1917}: mátalos según te los encuentres",
		["{area:307}: kill these as you meet them"] = "{area:307}: mátalos según te los encuentres",
		["{area:3317} flight master"] = "Maestro de vuelo de {area:3317}",
		["{area:348} well"] = "Pozo de {area:348}",
		["{area:355}: kill these as you meet them"] = "{area:355}: mátalos según te los encuentres",
		["{item:8704}, a rare drop"] = "{item:8704}, botín poco común",
		["{npc:14731}'s lunch"] = "El almuerzo de {npc:14731}",
		["{npc:14731}, inside"] = "{npc:14731}, dentro",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, en la cima de {area:354}",
		["{npc:7801}'s camp"] = "Campamento de {npc:7801}",
		["{zone:1425} first, then {area:75} and the {zone:1419}."] = "Primero {zone:1425}, luego {area:75} y {zone:1419}.",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "\"Lobo de mar\" MacKinley, en el piso superior: el cargamento de Stoley desde {zone:1446}",
		["Back to {area:1099}"] = "De vuelta a {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Vuelve con {npc:11548} al santuario; mantente al oeste de los guardias de {area:3137}.",
		["Back to {object:3202}"] = "De vuelta a {object:3202}",
		["Below ground"] = "Bajo tierra",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:35}"] = "Vuela a {area:35}",
		["Fly to {area:976}"] = "Vuela a {area:976}",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and Magatha are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Vuela a {zone:1456}; está de camino a {area:1099}. ¿Aún no tienes esa ruta de vuelo? Vuela a {area:378} y cabalga al oeste por {zone:1412}. Hamuul y Magatha están en {area:1639}; los druidas y paladines entrenan aquí ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Sigue el camino hacia el norte hasta {area:1237}, el campamento de la Horda.",
		["Frayfeather Hippogryphs"] = "Hipogrifos Plumavieja",
		["Hippogryph nests"] = "Nidos de hipogrifo",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Guarda {quest:3444}: el cofre de {npc:7771} se abre en una visita posterior.",
		["Northspring harpies"] = "Arpías Nortearroyo",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}."] = "De camino por {zone:1454} hacia el maestro de vuelo, entra en La Calada: {npc:7010} recoge el informe de insectos de {zone:1446}.",
		["Pestlezugg's samples come from {zone:1449}."] = "Las muestras de Morterozugg vienen de {zone:1449}.",
		["Rage Scar yetis"] = "Yetis Estigmodio",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Cabalga hacia el este por el camino desde el Puesto del Hachazo. {npc:11548} espera en {area:1235}, junto al camino, a pocos pasos al oeste de {area:3137}, de la Alianza: llega desde el oeste y evita a los Centinelas de Azshara y a Jarrodenus (élite).",
		["Ride into {zone:1447}"] = "Entra en {zone:1447}",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Cabalga hacia el sur por el camino hasta {area:1938}; {npc:7771} acampa al lado. Desde aquí, el camino hacia el oeste baja a {zone:1449}, donde empieza la siguiente guía.",
		["South of Booty Bay, three Bloodsail ships lie off the {area:43}: {npc:2550}, {npc:2548} and {npc:2546} each stand on a deck with their crews. Swim out and work from ship to ship."] = "Al sur de Bahía del Botín, tres barcos de los Maresangre están frente al {area:43}: {npc:2550}, {npc:2548} y {npc:2546} están cada uno en una cubierta con sus tripulaciones. Nada hasta ahí y trabaja de barco en barco.",
		["Sprite Darters"] = "Duendes dardo",
		["The Bloodsail ships"] = "Los barcos Velasangre",
		["The Droffers' shop is a few steps further into the Drag."] = "La tienda de los Droffers está a pocos pasos más adentro de La Calada.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Las apariciones de Altonato rondan las ruinas justo al norte del santuario; los sátiros Haldarr acampan un poco más al norte.",
		["The Northspring harpies nest on the ridges in the far north-west, past the giants' hills. The Windcallers heal, so kill them first and pull one at a time."] = "Las arpías Fuenteboreal anidan en las crestas del extremo noroeste, pasadas las colinas de los gigantes. Las Clamavientos curan, así que mátalas primero y atráelas de una en una.",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "El vuelo desde {area:75} aterriza en la plataforma superior de {area:35}. {npc:7406} tiene su taller en el anillo superior de la bahía.",
		["The flight lands at {area:117}; {npc:2497} stands by the {object:2076}."] = "El vuelo aterriza en {area:117}; {npc:2497} está junto al {object:2076}.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Los nidos de hipogrifo están en las colinas al sur, alrededor de {area:2522}; cada uno contiene un huevo para {object:142071}.",
		["The {object:142071}"] = "{object:142071}",
		["The {object:142071}, in the middle of town"] = "{object:142071}, en el centro del pueblo",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Son enemigos de élite: se anima a ir en grupo, busca gente con quien hacerlo. {npc:818} (47, élite) necesita un grupo de 2. Sáltatelo si estás solo: la ruta te hace picar la experiencia de vuelta.\nCuidado: dos guardias élite lanzadores, de nivel 45 alrededor, están con {npc:818} y se unen a la pelea junto con él.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Son enemigos de élite: se anima a ir en grupo, busca gente con quien hacerlo. El {quest:8552} necesita un grupo de 2. Sáltatelo si estás solo: la ruta te hace picar la experiencia de vuelta.",
		["Use the {item:3912} on Yenniku"] = "Usa {item:3912} en Yenniku",
		["Wandering Forest Walkers"] = "Caminabosques deambulantes",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["while he is alive: the gem fills; don't kill him"] = "mientras esté vivo: la gema se llena; no lo mates",
		["{area:1099} flight master"] = "Maestro de vuelo de {area:1099}",
		["{area:1236}: kill these as you meet them"] = "{area:1236}: mátalos según te los encuentres",
		["{area:1237} flight master"] = "Maestro de vuelo de {area:1237}",
		["{area:35} first, then {zone:1447}, {zone:1444} and {zone:1446}."] = "Primero {area:35}, luego {zone:1447}, {zone:1444} y {zone:1446}.",
		["{area:35} flight master"] = "Maestro de vuelo de {area:35}",
		["{area:976}'s Auction House is the last one before Un'Goro. There, {npc:9623} (Chasing {npc:9623}) asks for a {item:10561}, an {skill:202} item, before her escort: buy one here if you want that chain."] = "La casa de subastas de {area:976} es la última antes de Un'Goro. Allí {npc:9623} (En busca de {npc:9623}) pide un {item:10561}, un objeto de {skill:202}, antes de su escolta: compra uno aquí si quieres esa cadena.",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904}, sobre los Zancaolas y Zancaprofundas del agua",
		["{item:18958}, from the Sea Sprays"] = "{item:18958}, de los Rocíos marinos",
		["{npc:2487}, on the balcony of the same building"] = "{npc:2487}, en el balcón del mismo edificio",
		["{npc:2491} sits in the {area:35} inn."] = "{npc:2491} está sentado en la posada de {area:35}.",
		["{npc:2491}, in the inn"] = "{npc:2491}, en la posada",
		["{npc:5594}, inside"] = "{npc:5594}, dentro",
		["{npc:5769}, on the {area:1639}"] = "{npc:5769}, en {area:1639}",
		["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117} da vueltas por {area:1235}: mira dentro del círculo del mapa",
		["{npc:6746}, at the inn: for Hamuul"] = "{npc:6746}, en la posada: para Hamuul",
		["{npc:6986}, the Drag"] = "{npc:6986}, La Calle Mayor",
		["{npc:7010}, the Drag"] = "{npc:7010}, La Calada",
		["{npc:7406}, inside"] = "{npc:7406}, dentro",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: los osos están en {zone:1448}",
		["{npc:7854}, inside"] = "{npc:7854}, dentro",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
		["{quest:3761} is gathered in the next guide."] = "{quest:3761} se recoge en la siguiente guía.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, botín raro",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
		["{zone:1456} flight master"] = "Maestro de vuelo de {zone:1456}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Retrocede unos pasos hacia el oeste hasta la Granja Piedra Vil, la primera granja del camino; {npc:10778} espera en la casa.",
		["Back north-east to {area:251}."] = "Vuelve al noreste, a {area:251}.",
		["Back to {area:976}"] = "Vuelve a {area:976}",
		["Below ground"] = "Bajo tierra",
		["Boat to {area:16727}"] = "Barco a {area:16727}",
		["Bridge into {area:254}"] = "Puente hacia {area:254}",
		["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Cuidado: los trabajadores Gorishi pueden pedir ayuda en 25 metros cuando bajan del 45% de vida; los silíticos lanzan {spell:8137} y los túnelers y el guardia del panal usan {spell:14120}.",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "Cuidado: los Trabajadores Gorishi que bajan del 45% de salud tienen un 50% de probabilidad de pedir ayuda a los aliados a menos de 25 m. Los Guardias de la colmena (54) y la Reina están dentro de la colmena: ve a por los Trabajadores y las Avispas de fuera.",
		["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Cuidado: hay muchos ravasaurios rondando la zona, así que es fácil atraer a varios a la vez.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Cruza el sur del cráter hasta el pilón de los acantilados occidentales.",
		["Eastern Pylon"] = "Pilón del este",
		["Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Equípate {quest:5405}: las piedras de la Plaga solo caen mientras lo llevas.",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Fly to {area:1497}"] = "Vuela a {area:1497}",
		["Fly to {area:1637} and train before the boat to {area:16727}: the {zone:1458} stop later in this guide has no Hunter or Shaman trainer."] = "Vuela a {area:1637} y entrena antes del barco a {area:16727}: la parada en {zone:1458} más adelante en esta guía no tiene instructor de cazador ni de chamán.",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Sigue los acantilados hacia el sur hasta {quest:3821}, la colina de los ogros Pirontraña. Los restos de {npc:9136} están al pie.",
		["From here on pick up every {npc:271301} (blue, green, red, yellow) and every {quest:3761} pile you pass: 20 for Hamuul, and 5 more for Pestlezugg if you carry {quest:4496}."] = "A partir de aquí recoge cada {npc:271301} (azul, verde, rojo, amarillo) y cada montón de {quest:3761} que encuentres: 20 para Hamuul y 5 más para Morterozugg si llevas {quest:4496}.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {item:12814} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Desde {area:152}, sigue el camino al este hacia {zone:1422}. Las tiendas de la Cruzada Escarlata están justo pasada la granja de Piedramácula, entre {area:199} y {area:200}. Quema la tienda de mando con {item:12814} y planta el estandarte de la Plaga. Cuidado: los Escarlatas alrededor de las tiendas llegan a 54 y los invocadores lanzan hechizos: entra por el lado más cercano a la tienda de mando y deja en paz a los demás.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Desde {area:1938} cabalga hacia el oeste hasta la larga rampa que baja serpenteando a {zone:1449}; después sigue la pared norte del cráter hasta {area:541}, un campamento en las cuevas del acantilado. Aquí todos son neutrales.",
		["Gorillas"] = "Gorilas",
		["Into the {zone:1427}"] = "Hacia {zone:1427}",
		["Into {zone:1449}"] = "Hacia {zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "Guarda el paquete: {npc:10781} está en {zone:1458}. La siguiente guía empieza con {npc:10739} junto a {area:202}, al sureste de aquí.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Guarda la carta de {npc:10267}: {quest:4808} está en {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Guarda {quest:4147}, de {npc:9118}, y la carta de {npc:8737} para guías posteriores.",
		["Lar'korwi Mates"] = "Amigos de Lar'korwi",
		["Lashers and Threshers"] = "Latigadores y Trilladores",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Sal de {zone:1458} y cabalga hacia el este por el camino a través de {zone:1420} hasta {area:152}, el fuerte de los Renegados en la frontera.",
		["Leave {zone:2548} on foot to the north-west, north of {area:16685}, into the {zone:1418}."] = "Sal del {zone:2548} a pie hacia el noroeste, al norte de {area:16685}, hacia el {zone:1418}.",
		["Listen to {npc:8479}'s story once more."] = "Escucha la historia de {npc:8479} una vez más.",
		["North of Torwa, a dead Threshadon lies by the water. The {item:280417} lies on the ground a short ride west of {npc:9619}'s camp."] = "Al norte de Torwa hay un Trillodón muerto junto al agua. El {item:280417} está en el suelo, a poca distancia al oeste del campamento de {npc:9619}.",
		["Northern Pylon"] = "Pilón del norte",
		["Only from level 53: her next errand is {quest:3822} (54), who walks the caves of {quest:3821} among ogres of 50-53."] = "Solo a partir del nivel 53: su siguiente encargo es {quest:3822} (54), que recorre las cuevas de {quest:3821} entre ogros de nivel 50-53.",
		["Out of the refuge"] = "Fuera del refugio",
		["Power Crystals and soil"] = "Cristales de poder y tierra",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Baja por el lado este del cráter hasta el pilón de los acantilados orientales.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Cabalga hacia el norte por el lado este. La jungla está llena de Latigadores y Trilladores pétalo de sangre.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Dinosaur Bones lie on the ground among the Stegodons and drop from the Diemetradons nearby, which also carry the scales {npc:9998} wants. Careful: the Stegodons are elites (52-53): pick the bones up around them, don't pull them; the Elder Diemetradons are 53-55, take the smaller ones. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. Bloodpetal Trappers grow in the jungle there. Careful: the biggest Trappers are 53: pull them one at a time."] = "Cabalga hacia el suroeste hasta {area:537}, el volcán del centro del cráter. Los Despellejadores Sangrepétalo crecen al pie.\nAl sur de las aguas termales hay Huesos de dinosaurio en el suelo entre los Stegodons, y también los sueltan los Diemetradones cercanos, que llevan además las escamas que quiere {npc:9998}. Cuidado: los Stegodons son élite (52-53): recoge los huesos a su alrededor sin atraerlos; los Diemetradones viejos son de nivel 53-55, ve a por los pequeños. Los Ravasaurios cazan en manada en el suroeste: sus garras son para {npc:8659}, y de vez en cuando uno lleva Un diario destrozado (botín raro: acepta su misión solo si te sale). Evita a Gruff, un Stegodon de nivel 57.\nCabalga hacia el suroeste por los acantilados del oeste. Los Tramperos Sangrepétalo crecen en esa jungla. Cuidado: los Tramperos más grandes son de nivel 53: atráelos de uno en uno.",
		["Scarlet forward camp"] = "Campamento avanzado Escarlata",
		["Sentry Braziers"] = "Braseros de centinela",
		["Stegodons and ravasaurs"] = "Stegodons y ravasaurios",
		["The Anvilrage dwarves of your {area:1584} run: {npc:9077}, in {area:340}."] = "Los enanos Yunquefuria de tu incursión en {area:1584}: {npc:9077}, en {area:340}.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Los Amigos de Lar'korwi merodean por la jungla al noroeste de {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Los grupos de cristales están por todo el cráter, muchos alrededor de {area:537}. Coge unos cuantos de más de cada color para los pilones.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "El cajón de la expedición está en un campamento abandonado de la jungla oriental.",
		["The expedition's lost equipment lies in the south-west jungle."] = "El equipo perdido de la expedición está en la jungla del suroeste.",
		["The gorillas live on the north-east plateau: {npc:9619} wants two pelts of each kind, and the Thunderers (52-53) are the biggest. Stay out of the deepest cave: {npc:9622} lives there."] = "Los gorilas viven en la meseta del noreste: {npc:9619} quiere dos pieles de cada tipo, y los Atronadores (52-53) son los más grandes. No entres en la cueva más profunda: allí vive {npc:9622}.",
		["The hearth lands in {area:976}: {npc:11758} takes the {area:983}."] = "La piedra de hogar te deja en {area:976}: {npc:11758} recibe {area:983}.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "La montaña te deja salir junto a {area:252}, lleno de orcos de nivel 55-57. Sigue el camino hacia el este por los acantilados del norte hasta el campamento de la Horda en {area:251}.",
		["The pylon stands on the slope east of the refuge."] = "El pilón está en la ladera al este del refugio.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "La balsa está en la orilla del lago del sureste; la mochila pequeña está en el agua, a su lado.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}. Careful: the Lurkers reach 54 and the Tar Lords stand among them: take the Tar Beasts (50-51) and Creepers (51-52)."] = "Los pozos de alquitrán están justo al sur del refugio. Las Bestias Tar, los Rondadores Tar y los Trepadores Tar sueltan el {item:11834}. Cuidado: los Rondadores llegan a nivel 54 y los Señores Tar están entre ellos: ve a por las Bestias Tar (50-51) y los Trepadores (51-52).",
		["The {npc:9167} fly over the western cliffs around the pylon. Careful: the biggest are 54: pull them one at a time."] = "Los {npc:9167} vuelan sobre los acantilados del oeste, alrededor del pilón. Cuidado: los más grandes son de nivel 54; atráelos de uno en uno.",
		["To {area:976}"] = "A {area:976}",
		["Un'Goro first, then {area:340}, the {zone:1427} and the {zone:1428}."] = "Primero Un'Goro, luego {area:340}, {zone:1427} y {zone:1428}.",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Piso de arriba",
		["Use the Mangled Journal to start it"] = "Usa Un diario destrozado para empezarla",
		["Use the scale to start {quest:87494}, for {npc:9619}"] = "Usa la escama para empezar {quest:87494}, para {npc:9619}",
		["Western Pylon"] = "Pilón del oeste",
		["the wooden sign beside {npc:9997}, by the flight master: the {npc:9167} (51-54) come on the pylon loop"] = "el cartel de madera junto a {npc:9997}, al lado del maestro de vuelo: los {npc:9167} (51-54) se hacen en la ruta de los pilones",
		["{area:1584} is a dungeon for a group of five from about level 48, the biggest in the mountain: its Anvilrage dwarves are this quest's, and you need not go further in than they are. Its portal is deep inside the mountain, down the chain walkways from the bridge.\nInside: the Anvilrage Guardsmen, Wardens and Footmen. Then back out of the portal and on through the mountain's southern exit to the {zone:1428}."] = "{area:1584} es una mazmorra para un grupo de cinco desde el nivel 48 más o menos, la mayor de la montaña: sus enanos Yunquefuria son los de esta misión, y no hace falta adentrarse más allá de ellos. Su portal está en lo más profundo de la montaña, bajando por las pasarelas de cadenas desde el puente.\nDentro: los Guardias, Celadores y Soldados Yunquefuria. Luego vuelve a salir por el portal y sigue por la salida sur de la montaña hasta {zone:1428}.",
		["{area:250}: kill these as you meet them"] = "{area:250}: mátalos según te los encuentres",
		["{area:340} flight master"] = "Maestro de vuelo de {area:340}",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340} está construido en los acantilados del borde oeste de {zone:1418}.",
		["{area:538}: kill these as you meet them"] = "{area:538}: mátalos según te los encuentres",
		["{item:10575}, from the hoard"] = "{item:10575}, del tesoro",
		["{item:11116}, a rare drop"] = "{item:11116}, botín raro",
		["{item:12814}, from the {object:176092} next to Derrington: {quest:5096}, done on the way back"] = "{item:12814}, de {object:176092} junto a Derrington: {quest:5096}, hecha a la vuelta",
		["{item:280459}, a rare drop from the ravasaurs and Diemetradons"] = "{item:280459}, botín raro de los ravasaurios y los Diemetradones",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} te envía con {npc:9298} en {zone:1452}: guárdala.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "El goblin {npc:10302} está en {area:543}, justo al este del pilón.",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, junto al maestro de murciélagos",
		["{npc:5204}, near Cuely in the Apothecarium"] = "{npc:5204}, cerca de Cuely en el Apotecarium",
		["{npc:5594}, inside"] = "{npc:5594}, dentro",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} está en {object:36082}.",
		["{npc:7876} stands beside the wind rider master."] = "{npc:7876} está junto al maestro de jinetes del viento.",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, al fondo de la cueva; bajo tierra",
		["{npc:9117}, below ground"] = "{npc:9117}, bajo tierra",
		["{npc:9166} (50-52) fly over the east of the crater, from the slopes below the refuge southward; their webbed scales are for {npc:9998}, and {npc:9997}'s sign wants ten of them. Leave the {npc:9167} over the west for the pylon loop."] = "Los {npc:9166} (50-52) vuelan sobre el este del cráter, desde las laderas bajo el refugio hacia el sur; sus escamas palmeadas son para {npc:9998}, y el cartel de {npc:9997} pide diez. Deja los {npc:9167} del oeste para la ruta de los pilones.",
		["{npc:9167}: kill these as you meet them"] = "{npc:9167}: mátalos según te los encuentres",
		["{npc:9618}, just outside"] = "{npc:9618}, justo fuera",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} acampa en la esquina sureste del cráter.",
		["{npc:9619}'s camp is in the south-east corner, a short ride from the {area:1942}."] = "El campamento de {npc:9619} está en la esquina sureste, a poca distancia de {area:1942}.",
		["{npc:9619}: {quest:4289}, the gorillas of the north-east plateau on the pylon loop"] = "{npc:9619}: {quest:4289}, los gorilas de la meseta del noreste en la ruta de los pilones",
		["{npc:9619}: {quest:87492}, a short ride west of his camp"] = "{npc:9619}: {quest:87492}, a poca distancia al oeste de su campamento",
		["{npc:9619}: {quest:87494}, if the scale dropped"] = "{npc:9619}: {quest:87494}, si te salió la escama",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "Después {npc:9623} pide una {item:10561}, un objeto de {skill:202}. Omítela salvo que tengas una.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, el robot de la meseta; bajo tierra",
		["{npc:9706}, by the dock: for {quest:4324} at {area:251}, later in this guide"] = "{npc:9706}, en el muelle: para el {quest:4324} en {area:251}, más tarde en esta guía",
		["{npc:9997}, beside the flight master"] = "{npc:9997}, junto al maestro de vuelo",
		["{npc:9998}, at the entrance"] = "{npc:9998}, en la entrada",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{object:175894}, beside the house; inside"] = "{object:175894}, junto a la casa; dentro",
		["{quest:2995}'s work is not in this guide: burn the {object:144073}, Notes and Records in the elves' camps around {area:350}, in {zone:1425} & {zone:1419} (its Highvale step). Load that guide for the arrows."] = "El trabajo de {quest:2995} no está en esta guía: quema {object:144073}, las notas y los registros en los campamentos élficos alrededor de {area:350}, en la guía de {zone:1425} y {zone:1419} (su paso de Vallealto). Carga esa guía para las flechas.",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} está en el suelo a los pies de {npc:8479}; {quest:3462} está a su lado.",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} recorre las cuevas y túneles de mina de {quest:3821}; si no está, limpia los ogros de las entradas hasta que vuelva.",
		["{quest:4081}: the Anvilrage dwarves, inside"] = "{quest:4081}: los enanos Yunquefuria, dentro",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449}: mata a estos según te los encuentres",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "De vuelta al norte a {area:1763}. Llena la cantimplora de Greta en la poza de la luna corrupta en el centro del campamento sur.",
		["Back north to {npc:8420} with the rune, then south-west along the road."] = "Vuelve al norte con {npc:8420} con la runa y luego ve al suroeste por el camino.",
		["Back north-west to {npc:8420}."] = "Vuelve al noroeste con {npc:8420}.",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "Las atalayas de Derrington y el caldero de Vandis se hacen en una visita posterior: guárdalas.",
		["Diseased Wolves"] = "Lobos malsanos",
		["Druid trainer"] = "Instructor de druidas",
		["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "Cada uno de los tres oficiales del campamento (53) lleva un sello: {npc:247006} en el centro del campamento, {npc:247013} en su extremo este y {npc:246991}, que patrulla su mitad oeste: enfréntate a él en el lado este de su recorrido, donde apunta la Flecha.\nCuidado: el {npc:250023}, élite de nivel 55-57, está en el borde oeste del campamento, cerca del extremo del recorrido de Hawkhelm: espera a que Hawkhelm vuelva al este.",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Al este de Puesto del Veneno, el valle lleno de cráteres donde deambulan Bestias entrópicas y Horrores. Mata dos de cada y luego camina hasta cada uno de los tres cráteres de agua vil.",
		["Fly to {area:1237}"] = "Vuela a {area:1237}",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:431}"] = "Vuela a {area:431}",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {item:12814} and plant the Scourge banner. Careful: the Scarlets around the tents reach 54 and the Invokers cast: come in from the side nearest the command tent and leave the others be."] = "Desde {area:152}, sigue el camino al este hacia {zone:1422}. Las tiendas de la Cruzada Escarlata están justo pasada la granja de Piedramácula, entre {area:199} y {area:200}. Quema la tienda de mando con {item:12814} y planta el estandarte de la Plaga. Cuidado: los Escarlatas alrededor de las tiendas llegan a 54 y los invocadores lanzan hechizos: entra por el lado más cercano a la tienda de mando y deja en paz a los demás.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Acampa junto a {area:202}, al sureste de {area:200}.",
		["Inside"] = "Dentro",
		["Keep {quest:8465} for {zone:1452}."] = "Guarda {quest:8465} para {zone:1452}.",
		["Makrinni Burrowers"] = "Excavadores Makrinni",
		["Northern crater"] = "Cráter norte",
		["On north-east across the middle of {zone:1447}: {npc:235903} camps by the road."] = "Sigue al noreste cruzando el centro de {zone:1447}: {npc:235903} acampa junto al camino.",
		["Paladin trainer"] = "Instructor de paladines",
		["Ride back west to {area:1237}."] = "Vuelve al oeste a {area:1237}.",
		["Ride east to the ruins on the coast. The four tablets lie among the ruins, guarded by Spitelash naga (52-55): pull them one at a time."] = "Cabalga al este hasta las ruinas de la costa. Las cuatro tablillas están entre las ruinas, custodiadas por nagas Látigo de Ira (52-55): atráelos de uno en uno.",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}, just north of the blood elves."] = "Cabalga al noreste hasta el campamento del goblin en los acantilados sobre {area:1227}, justo al norte de los elfos de sangre.",
		["Ride south to the northern edge of the {area:1221}. The Spitelash Sirens and Myrmidons (50-52) there carry {npc:8420}'s rune; it doesn't drop often, so work your way along the edge until it does."] = "Ve al sur hasta el borde norte de {area:1221}. Las Sirenas y los Mirmidones Látigo de Ira (50-52) de allí llevan la runa de {npc:8420}; no cae a menudo, así que recorre el borde hasta que salga.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Cabalga al suroeste pasando la granja de Piedramácula y sigue el camino al oeste de vuelta a {area:152}.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there: on Forever the Sin'dorei Tome beside it then asks for the seals of the camp's three officers."] = "El campamento de Rimtori está en el extremo este del campamento base. Lee el {object:151286} que hay allí: en Forever, el Tomo Sin'dorei de al lado pide entonces los sellos de los tres oficiales del campamento.",
		["Scarlet forward camp"] = "Campamento avanzado Escarlata",
		["South-west along the road: {npc:235903} takes the satyrs."] = "Al suroeste por el camino: {npc:235903} recibe los sátiros.",
		["Southern crater"] = "Cráter sur",
		["Southern {area:1763}"] = "Sur de {area:1763}",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "La aldea de los furbolgs Deadwood está justo al sur del Santuario. Cada muerte de Deadwood también sube tu reputación de {area:1769}; guarda las plumas de tocado.",
		["The Horde camp just north of {area:1763}."] = "El campamento de la Horda justo al norte de {area:1763}.",
		["The Legashi satyrs"] = "Los sátiros Legashi",
		["The Makrinni Burrowers (50-51) dig in the sands just east of the ruins, on the way north-east; they and the buried caches there give up the Highborne Treasure Fragments."] = "Los Excavadores Makrinni (50-51) cavan en la arena justo al este de las ruinas, de camino al noreste; ellos y los alijos enterrados allí dan los Fragmentos de tesoro de los Altonato.",
		["The apprentice at the top of the tower sends you back down."] = "El aprendiz de lo alto de la torre te manda de vuelta abajo.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}. {npc:8420}'s four pieces of equipment lie in the crates around the camp; the Blood Elf Arcanists carry {npc:247473}'s wand.\nCareful: a {npc:250023}, a level 55-57 elite, stands at the west edge of the camp: work the blood elves from its east side."] = "Los elfos de sangre acampan en los acantilados del noreste, junto a {area:1227}. Las cuatro piezas de equipo de {npc:8420} están en las cajas alrededor del campamento; los Arcanistas elfos de sangre llevan la varita de {npc:247473}.\nCuidado: un {npc:250023}, élite de nivel 55-57, está en el borde oeste del campamento: enfréntate a los elfos de sangre desde su lado este.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "El diario está en la granja, el armario dentro y la letrina detrás. Un {npc:10816} lleva la llave de la letrina; {npc:10836} aparece al abrir la letrina y lleva la llave del armario.",
		["The druids' camp is just past the border."] = "El campamento de los druidas está justo pasada la frontera.",
		["The middle of {zone:1454}"] = "El centro de {zone:1454}",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "El camino acaba en {npc:15395}, fuera del túnel de {area:1769}, en el extremo noreste.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east. Careful: the biggest are 54: pull them one at a time."] = "Los lobos deambulan por los campos entre Andorhal, {area:200} y {area:202}. Termínalos en el camino de vuelta al este. Cuidado: los más grandes son de nivel 54; atráelos de uno en uno.",
		["The {area:1763} moonwell"] = "La poza de la luna de {area:1763}",
		["The {object:661778} stands just south of the vale, by the road north: its bauble starts a quest for {npc:9996} at {area:1997}."] = "{object:661778} está justo al sur del valle, junto al camino del norte: su chuchería inicia una misión para {npc:9996} en {area:1997}.",
		["Upstairs"] = "Piso de arriba",
		["Western crater"] = "Cráter oeste",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Te perdiste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{area:1221}: kill these as you meet them"] = "{area:1221}: mátalos según te los encuentres",
		["{area:1237} flight master"] = "Maestro de vuelo de {area:1237}",
		["{area:200} farmhouse"] = "Granja de {area:200}",
		["{item:12814}, from the {object:176092}"] = "{item:12814}, de {object:176092}",
		["{item:12814}, from the {object:176092} next to Derrington"] = "{item:12814}, de {object:176092} junto a Derrington",
		["{item:246680}, from the Blood Elf Arcanists"] = "{item:246680}, de los Arcanistas elfos de sangre",
		["{item:246721}, from {npc:246991}"] = "{item:246721}, de {npc:246991}",
		["{item:246722}, from {npc:247013}"] = "{item:246722}, de {npc:247013}",
		["{item:246725}, from {npc:247006}"] = "{item:246725}, de {npc:247006}",
		["{item:277958}, from the Angerclaw bears"] = "{item:277958}, de los osos Zarpira",
		["{item:277959}, from the Felpaw wolves"] = "{item:277959}, de los lobos Zarpayel",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: las lechubestias están en {zone:1452}",
		["{npc:10920}, beside {npc:10921}: {quest:86577}, the organs of {zone:1448}'s bears and wolves"] = "{npc:10920}, junto a {npc:10921}: {quest:86577}, los órganos de los osos y lobos de {zone:1448}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, en el borde sur del campamento",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} da vueltas por aquí: mira dentro del círculo del mapa",
		["{npc:235903}: {quest:86746}, the satyrs north of the blood elves' camp"] = "{npc:235903}: {quest:86746}, los sátiros al norte del campamento de los elfos de sangre",
		["{npc:246152} in {zone:1420}; {zone:1454} has no paladin trainer"] = "{npc:246152} en {zone:1420}; {zone:1454} no tiene instructor de paladines",
		["{npc:247473}: {quest:91569}, a wand from the blood elves' arcanists"] = "{npc:247473}: {quest:91569}, una varita de los arcanistas elfos de sangre",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} en {zone:1412}; {zone:1454} no tiene instructor de druidas",
		["{npc:3326}, the {object:172960}"] = "{npc:3326}, {object:172960}",
		["{npc:8576}: {quest:91531}, for {npc:4485} in {zone:1454}"] = "{npc:8576}: {quest:91531}, para {npc:4485} en {zone:1454}",
		["{npc:8578}'s camp"] = "Campamento de {npc:8578}",
		["{npc:8587}: the tome goes to {npc:3326} in {zone:1454}"] = "{npc:8587}: el tomo se entrega a {npc:3326} en {zone:1454}",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}, en el lado oeste del campamento",
		["{quest:5096} needs a {item:12814} to torch the command tent: take one from the {object:176092} next to {npc:10837}."] = "{quest:5096} necesita una {item:12814} para quemar la tienda de mando: coge una de {object:176092} junto a {npc:10837}.",
		["{quest:91538}: for {npc:8587} in {area:1237}"] = "{quest:91538}: para {npc:8587} en {area:1237}",
		["{zone:1422} and the {area:152} first, then {zone:1447} and {zone:1448}."] = "Primero {zone:1422} y {area:152}, luego {zone:1447} y {zone:1448}.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "Vuelve al sur con {npc:7775}. Guarda el elixir y no lo bebas todavía: te mata, y así es como conocerás más tarde a Gaeriyan junto a {area:976}.",
		["Bring the {npc:10042} to {npc:9996} at {area:1997} and click on it to hand it over."] = "Lleva {npc:10042} a {npc:9996} en {area:1997} y haz clic en él para entregárselo.",
		["Chillwind chimaeras"] = "Quimeras venfresco",
		["Fly to {area:1099}"] = "Vuela a {area:1099}",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:431}"] = "Vuela a {area:431}",
		["Gregor's quests lead to other zones: keep them."] = "Las misiones de Gregor llevan a otras zonas: guárdalas.",
		["Ice Thistle yetis"] = "Yetis Cardo Nevado",
		["Into {zone:1452}"] = "Hacia {zone:1452}",
		["Linken's letter"] = "La carta de Linken",
		["Raging Owlbeasts"] = "Lechubestias enfurecidas",
		["Ride south from the tunnel: {npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "Cabalga al sur desde el túnel: {npc:9298} acampa entre las pozas humeantes de {area:2246}, al oeste del valle.",
		["The Jadefire moonwell"] = "La poza de la luna Fuego de Jade",
		["The Matriarchs and Patriarchs that carry Umi's horns are 56-58: leave them for that later stop."] = "Las matriarcas y patriarcas que llevan los cuernos de Umi son de nivel 56-58: déjalos para esa parada posterior.",
		["{area:2246}: kill these as you meet them"] = "{area:2246}: mátalos según te los encuentres",
		["{area:2255} flight master"] = "Maestro de vuelo de {area:2255}",
		["{area:2255} is the goblin town on the east side of the valley, past the owlbeast hills."] = "{area:2255} es el pueblo goblin del lado este del valle, pasadas las colinas de los lechúcicos.",
		["{area:2408} flight master"] = "Maestro de vuelo de {area:2408}",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, la recompensa de {npc:7775}",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}, en la poza de la luna Fuego de Jade",
		["{item:12771}: about one Winterfall furbolg in ten carries one; keep killing them until it drops"] = "{item:12771}: unos diez de los que lo llevan; sigue matándolos hasta que caiga",
		["{npc:10431}, inside"] = "{npc:10431}, dentro",
		["{npc:10881} and {npc:14728} stand on {area:1641}. Each of Rumstag's donations takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "{npc:10881} y {npc:14728} están en {area:1641}. Cada donación de Rumstag toma sesenta lana, seda o paño de mago de tus bolsas: entrega lo que lleves, sáltate el resto.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} está justo en la salida a {zone:1452} del túnel de {area:1769}, por donde sales.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} en {area:1639}; {npc:246344}",
		["{npc:9076} stands on {area:1639}."] = "{npc:9076} está en {area:1639}.",
		["{npc:9087} buys {item:11040} grown from your {quest:3761}. {quest:3782} wants ten, and the {item:11020} gives one try every ten minutes: take it only if you already have the grain."] = "{npc:9087} compra {item:11040} cultivados a partir de tu {quest:3761}. El {quest:3782} quiere diez, y el {item:11020} da un intento cada diez minutos: cógelo solo si ya tienes el grano.",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, en el lado oeste del Santuario",
		["{npc:9996}'s kitten"] = "El gatito de {npc:9996}",
		["{npc:9996}: the {quest:86612}"] = "{npc:9996}: {quest:86612}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} espera en {zone:1450}: guárdala para más tarde.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se entrega en el {object:176091} de {zone:1448}, en un viaje posterior.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, botín raro de los fúrbolgs Nevada",
		["{zone:1452} and {zone:1448}, then {zone:1444} and {zone:1456}."] = "{zone:1452} y {zone:1448}, luego {zone:1444} y {zone:1456}.",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "Ambas donaciones de {item:14047} se entregan más tarde en la ruta: guarda sesenta {item:14047} para cada una si las quieres.",
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "El agua purificada se entrega en {area:2479}, en {zone:1448}: guárdala para más adelante.",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:392}"] = "Vuela a {area:392}",
		["Fly to {zone:1454} and train."] = "Vuela a {zone:1454} y entrena.",
		["In the {object:172958}."] = "En {object:172958}.",
		["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "En el {object:172961}. Cada donación toma sesenta lana, seda o paño de mago de tus bolsas: entrega lo que lleves, sáltate el resto.",
		["Inside"] = "Dentro",
		["Into {zone:1411}"] = "Hacia {zone:1411}",
		["Lady Sylvanas holds the {object:36126}."] = "Lady Sylvanas está en {object:36126}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "El taller de Liv está en el extremo norte de los muelles de {area:392}; {object:149036} está dentro.",
		["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "Solo con el {quest:79095} de la tienda de alquimia de {area:159} en las bolsas (la guía de libros de la biblioteca)",
		["Paladin trainer"] = "Instructor de paladines",
		["Ride east out of the {zone:1458} along the road; the {area:152} guards the way into the {zone:1422}."] = "Cabalga al este desde el {zone:1458} por la carretera; el {area:152} guarda el camino hacia el {zone:1422}.",
		["Upstairs"] = "Piso de arriba",
		["Zeppelin to {zone:1458}"] = "Zepelín a {zone:1458}",
		["{area:392} flight master"] = "Maestro de vuelo de {area:392}",
		["{area:392}, {zone:1454} and the {zone:1458}, then into the Plaguelands."] = "{area:392}, {zone:1454} y {zone:1458}, luego a las Tierras de la Peste.",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "La granja de {npc:10778} es la primera al este del {area:152}. Los necrófagos farfullantes de la granja llevan la otra mitad de su amuleto; {npc:11075} guarda el caldero del campo.\nCuidado: uno o dos no muertos suelen luchar a su lado, y más señores del caldero pueden atacar tras usar el caldero.",
		["{npc:11615}: the termites are in {area:2627}, on the next guide"] = "{npc:11615}: las termitas están en {area:2627}, en la siguiente guía",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: guárdala para {zone:1451}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} en {zone:1456}; {zone:1454} no tiene instructor de paladines",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} acampa en la orilla, justo al norte de {area:392}.",
		["{npc:6522} stands in the {object:36073}."] = "{npc:6522} está en {object:36073}.",
		["{npc:7010} works in the Drag."] = "{npc:7010} trabaja en La Calle Mayor.",
		["{npc:8390} and {npc:8393} work in the Apothecarium."] = "{npc:8390} y {npc:8393} trabajan en el Apotecarium.",
		["{npc:8390} works in the Apothecarium."] = "{npc:8390} trabaja en el Apothecarium.",
		["{npc:8393}, beside him"] = "{npc:8393}, a su lado",
		["{npc:8403}, nearby"] = "{npc:8403}, cerca",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} se entrega a {npc:10778} en {zone:1422}: guárdala.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A {item:13140} dropped: the Jaedenar Enforcers, Darkweavers, Warlocks and Legionnaires of Shadow Hold carry one now and then. Use it to start the quest, then free {npc:11018} from her cage in the cave's south end on your way out."] = "Te ha caído una {item:13140}: los Déspotas Jaedenar, Tejeoscuros, Brujos y Legionarios de Bastión de las Sombras la llevan de vez en cuando. Úsala para empezar la misión y luego libera a {npc:11018} de su jaula en el extremo sur de la cueva al salir.",
		["Andorhal watchtowers and silos"] = "Atalayas y silos de Andorhal",
		["Back south to the Sanctuary, a short ride."] = "Vuelve al sur, al Santuario; está cerca.",
		["Back to {area:2268}"] = "Vuelve a {area:2268}",
		["Below ground"] = "Bajo tierra",
		["Both quests lead to {zone:1451}: keep them."] = "Las dos misiones llevan a {zone:1451}: guárdalas.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Cuidado: {npc:10411} se vuelve invisible fuera de combate y llama a gárgolas Alarroca en cuanto empieza el combate. Solo hay 3 y reaparecen cada 15 min.",
		["Class trainer"] = "Instructor de clase",
		["Diseased Grizzlies"] = "Griseznos malsanos",
		["Fly to {area:1638}"] = "Vuela a {area:1638}",
		["Fly to {area:2268}"] = "Vuela a {area:2268}",
		["Fly to {area:272}"] = "Vuela a {area:272}",
		["Fly to {area:431}"] = "Vuela a {area:431}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Sigue el camino hacia el este desde {zone:1422}, cruza el río y atraviesa todas {zone:1423} hasta la capilla de {object:92525}, en el extremo este.",
		["Free Darrowshire Spirits: talk to them"] = "Libera a los espíritus de Villa Darrow: habla con ellos",
		["From the tunnel's {zone:1452} exit, ride south to {area:2246}."] = "Desde la salida del túnel en {zone:1452}, cabalga al sur hasta {area:2246}.",
		["Inside"] = "Dentro",
		["Into {zone:1423}"] = "Hacia {zone:1423}",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Guarda {quest:5152}: {npc:10927} vive en {area:197}, en {zone:1422}.",
		["Mark {npc:10902} with the {item:12815}"] = "Marca la {npc:10902} con la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca la {npc:10903} con la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca la {npc:10904} con la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca la {npc:10905} con la {item:12815}",
		["Moontouched Owlbeasts"] = "Lechubestias lunadón",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Los Cachorros de can de la Peste y los Murcipestes recorren las colinas al norte de {area:2260}, y las Larvas carroñeras se arrastran entre ellos; avanza hacia el norte, hacia {area:2627}.",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel; Plaguebats and Carrion Grubs share the ground. Careful: the biggest Plaguehounds are 56, pull them one at a time.\nThe shattered sword lies on the ground north-west of the lake."] = "Los canes de peste y sus cachorros recorren las orillas del lago al suroeste de la capilla; los murcipestes y las larvas carroñeras comparten el terreno. Cuidado: los canes de peste más grandes son de nivel 56, atráelos de uno en uno.\nLa espada rota está en el suelo al noroeste del lago.",
		["Pristine Yeti Horns"] = "Cuernos de yeti prístinos",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Vuelve al sur hasta {area:272} y vuela a {area:2268}.",
		["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "Ve al este por el camino hasta {zone:1423}. {npc:1855} vive en una casita junto a {area:2619}, justo al norte del camino en la frontera; sus tres cacerías están en la zona de esta guía.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Careful: they are 57-58: pull them one at a time.\nCareful: Hailspite, level 60 elites, gather in the snowfields south-east of {area:2255}, where a few Moontouched Owlbeasts roam too: stay on the slopes north of town."] = "Ve al este hasta {area:2255} y sal de allí hacia el norte; las lechubestias lunadón recorren las colinas de las laderas sur de {area:2241}. Cuidado: son de nivel 57-58: atráelas de una en una.\nCuidado: los Hailspite, élites de nivel 60, se reúnen en los campos nevados al sureste de {area:2255}, donde también rondan algunas lechubestias lunadón: no te salgas de las laderas al norte del pueblo.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Sube por el camino hacia el norte desde {area:272}. La casa de {npc:10927} está junto al camino en {area:197}, y el monumento de {npc:10936} está en el cementerio de detrás.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Ve al noroeste hacia Andorhal. {npc:10667} espera en la posada en ruinas del lado oeste del pueblo; los esqueletos de dentro son de nivel 54-57, así que mantente por los bordes.",
		["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Ve al sur hasta {area:2264}, por el camino. {item:15447} se echa a perder en diez minutos: mata rápido a la Plaga del pueblo y muele los siete trozos con {item:15454} enseguida.\nCuidado: los sirvientes ocultos piden ayuda en un radio de 25 m cuando bajan al 40 % de salud. Fuera de combate, además, se vuelven invisibles con {spell:10228}. Si piden ayuda dentro del pueblo, puede unirse al combate un gran número de enemigos. Luchar cerca de las afueras reduce este riesgo.\nCon {quest:5211} en tu registro (de {npc:11063}, al principio de esta guía), la Plaga alrededor del pueblo deja espíritus de Villa Darrow: habla con cada uno para liberarlo. Libéralos antes de empezar con {item:15447}.",
		["Ride south-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by each grain silo on the north side of town, one silo after another, to bring out Temporal Parasites (55-57): fight them one at a time and let the biggest go.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room.\nCareful: Skeletal Warlords, level 56-57 elites, stand by the first and second towers (the south-western and the western one): mark those towers from the far side of the doorway once the Warlord has turned away, and never pull one. Putridius (58, rare) walks among the silos."] = "Cabalga al suroeste hacia Andorhal. {npc:10667} espera en la posada en ruinas del lado oeste del pueblo. Ponte en la puerta de cada una de las cuatro torres con {item:12815} para marcarla; mantente en los bordes del pueblo. Usa {item:12627} junto a cada silo de grano del norte del pueblo, uno tras otro, para sacar a los parásitos temporales ({npc:10717}, 55-57): lucha con ellos de uno en uno y deja ir a los más grandes.\nCuidado: un {npc:10996}, un élite de nivel 58-59, puede estar en Andorhal, como en muchos otros puntos de {zone:1422}: dale espacio.\nCuidado: los señores de la guerra esqueléticos ({npc:1788}), élites de nivel 56-57, están junto a la primera y la segunda torre (la del suroeste y la del oeste): marca esas torres desde el lado lejano de la puerta cuando el señor de la guerra se haya dado la vuelta, y nunca atraigas a uno. Putridius (58, raro) camina entre los silos.",
		["Scarlet Crusade"] = "Cruzada Escarlata",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.\nCareful: a {npc:10996}, a level 58-59 elite, can stand in Andorhal, as at many other spots of the {zone:1422}: give it room."] = "Los Anales están entre los libros enmohecidos del ayuntamiento de Andorhal; ábrelos hasta encontrar el correcto.\nCuidado: puede haber un {npc:10996}, élite de nivel 58-59, en Andorhal, como en muchos otros puntos de {zone:1422}: guarda las distancias.",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass.\nCareful: Ziggurat Protectors (58, elite) stand by the ziggurats east and north-east of the town: take the mounds nearer the town and stay clear of them."] = "El libro está en la posada en ruinas de {area:2627}; los no-muertos del pueblo son de nivel 54-56, así que atráelos de uno en uno.\nLos montículos grandes de termitas están por todas las colinas al este de {area:2627}. Usa la {item:15042} en cada montículo que encuentres.\nCuidado: los protectores Ziggurat (58, élite) están junto a los zigurats al este y noreste del pueblo: ve a los montículos más cercanos al pueblo y mantente lejos de ellos.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La cabeza de la muñeca y sus dos costados están en las casas alrededor de {npc:10926}; únelos desde tus bolsas.",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "El cráneo está en {area:2622}, entre horrores apestados y monstruosidades de la Peste.",
		["To {area:197}"] = "A {area:197}",
		["Umi's horns, carried from your last {area:2255} stop: the yeti hills start just south-east of {area:2255}. Only Matriarchs and Patriarchs drop horns, and the Patriarchs reach 58: pull them one at a time."] = "Los cuernos de Umi, pendientes desde tu última parada en {area:2255}: las colinas de los yetis empiezan justo al sureste de {area:2255}. Solo las matriarcas y los patriarcas sueltan cuernos, y los patriarcas llegan al nivel 58: atráelos de uno en uno.",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Piso de arriba",
		["West to the {area:152} one last time."] = "Al oeste, hasta {area:152}, por última vez.",
		["West to the {area:152}."] = "Al oeste, hasta {area:152}.",
		["Western & {zone:1423} & {zone:1448}"] = "Tierras de la Peste del Oeste, {zone:1423} & {zone:1448}",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Te perdiste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.",
		["Zaeldarr lurks just west of {area:2262}."] = "Zaeldarr acecha justo al oeste de {area:2262}.",
		["a message for {npc:11063} at {area:2268}"] = "un mensaje para {npc:11063} en {area:2268}",
		["{area:152} and both Plaguelands, then {zone:1448} and {zone:1452}."] = "{area:152} y las dos Tierras de la Peste, luego {zone:1448} y {zone:1452}.",
		["{area:2268} flight master"] = "Maestro de vuelo de {area:2268}",
		["{area:2277}: kill these as you meet them"] = "{area:2277}: mátalos según te los encuentres",
		["{area:2627}: kill these as you meet them"] = "{area:2627}: mata a estos según te los encuentres",
		["{area:272} flight master"] = "Maestro de vuelo de {area:272}",
		["{npc:10667}, upstairs"] = "{npc:10667}, en el piso de arriba",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "El fantasma de {npc:10926} está en las ruinas de {area:2262}, al suroeste.",
		["{npc:10927}, upstairs"] = "{npc:10927}, en el piso de arriba",
		["{npc:11016}, below ground"] = "{npc:11016}, bajo tierra",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} da vueltas por aquí: mira dentro del círculo del mapa",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} está al este del campamento maderero; {npc:11611} custodia el camino al noreste de {npc:11610}, hacia {area:190}.\nCuidado: hay guardias en la base de la torre y otro más la rodea patrullando. Despéjalos antes de enfrentarte a Durgen para que no se unan a la pelea.",
		["{npc:12384}, inside"] = "{npc:12384}, dentro",
		["{npc:3033} (Druids) trains on {area:1639}, {npc:246344} (Paladins) in the city too."] = "{npc:3033} (druidas) entrena en {area:1639}, {npc:246344} (paladines) también en la ciudad.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} en {area:1639}; {npc:246344}",
		["{npc:8530}: a {npc:11064} rises where one dies"] = "{npc:8530}: un {npc:11064} se alza donde muere uno",
		["{npc:8531}: leaves a spirit too"] = "{npc:8531}: también deja un espíritu",
		["{npc:8532}: leaves a spirit too"] = "{npc:8532}: también deja un espíritu",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it."] = "{quest:5086} están en {zone:1448}, en un viaje posterior: guárdala.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Los espíritus de {quest:5211} llegan con la parada en {area:2264} más adelante en esta guía: guárdala.",
		["{quest:5510}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5510}: los no-muertos de {area:2627} las sueltan mientras llevas la {item:12846}",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423}: mata a estos según te los encuentres",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
		["{zone:1456} flight master"] = "Maestro de vuelo de {zone:1456}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Vuelve a Viento del Sur y sube a la torre. Al remover la colmena de la cima salen Emboscadores Colmen'Ashi; uno lleva el {item:17346}.",
		["Back to {area:3425}"] = "Vuelve a {area:3425}",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "Consigue veinte Textos crepusculares codificados de los fieles de aquí, diez para {npc:15306} y diez para Ortell. Cógelos de los Vengadores Crepusculares y los Geoseñores; deja a los Atracallamas y los Clamapiedras (59-60).",
		["Dredge Crushers and Pincers"] = "Trituradores y Tenazarios",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Los Artilleros de arrastre, los Escórpidos Latigosólido y los Arácnidos de arena comparten la arena justo al norte del fuerte.",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Bebe el {item:11243} en el cementerio justo al este de {area:976}: te mata, y solo como fantasma puedes ver a {npc:9299}, en una grieta rocosa de las colinas justo al norte. Habla con él allí, luego corre de vuelta a tu cuerpo y resucita: la Lápida llamativa a la que te envía está en ese cementerio.",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Flayers and Rock Stalkers"] = "Cazadores y Acechadores de piedra",
		["Fly to {area:1637}"] = "Vuela a {area:1637}",
		["Fly to {area:541}"] = "Vuela a {area:541}",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Ve al norte por las dunas del oeste; los Trituradores de arrastre y los Tnazarios Latigosólido se extienden desde aquí hasta el fuerte.",
		["Inside"] = "Dentro",
		["Inside: {quest:4493}, if you took it in {zone:1454} on the {zone:1447} guide"] = "Dentro: {quest:4493}, si la cogiste en {zone:1454} en la guía de {zone:1447}",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Lleva a {npc:9999} al norte hasta {area:541}. Cuando se desmaye, usa {item:11804} en él para despertarlo.",
		["Mar'alith's next errand, Into the Maw of Madness, leads into {area:2744} among elites. Skip it."] = "El siguiente encargo de Mar'alith, Into the Maw of Madness, te lleva a {area:2744} entre élites. Sáltatelo.",
		["Only if you took {quest:4496} in {area:976} on the way here: the Gorishi of the {area:540}, south of {area:537}, drop the Scent Gland, and most of the crater's beasts and plants drop {item:11018}."] = "Solo si aceptaste {quest:4496} en {area:976} de camino aquí: los Gorishi de {area:540}, al sur de {area:537}, sueltan la Glándula de olor, y la mayoría de bestias y plantas del cráter sueltan {item:11018}.",
		["Paladin trainer"] = "Instructor de paladines",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Cabalga hacia el este hasta {area:537}, súbelo y usa {npc:10541} en la grieta de lava cerca de la cima; después vuelve al oeste con {npc:10302}.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Cabalga al noreste hasta {area:3077}; sales de {zone:1451} por el paso que hay al lado.",
		["Ride north-east to {area:3447}."] = "Cabalga al noreste hasta {area:3447}.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Cabalga al sureste hasta {area:3447}, bajo los acantilados de Un'Goro.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Cabalga al suroeste hasta las ruinas de {area:2738}. El {object:179565} para {npc:11801} está dentro de una de las casas en ruinas.",
		["Scare {npc:7583} with {item:12928}"] = "Asusta a {npc:7583} con {item:12928}",
		["Stonelash Flayers and Rock Stalkers roam the dunes north of {area:2744}, in the south-east of {zone:1451}."] = "Los desolladores Látigo Pétreo ({npc:11737}) y los acechadores de las rocas ({npc:11739}) recorren las dunas al norte de {area:2744}, en el sureste de {zone:1451}.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "El paso desde Un'Goro sale en {area:3077}, el cementerio del noreste de {zone:1451}. {npc:13220} está entre las tumbas.",
		["The spare texts from the cultists"] = "Los textos sobrantes de los fieles",
		["Twilight Vanguard"] = "Vanguardia Crepuscular",
		["Use the {item:11833} where the arrow points, inside the Gorishi hive of the {area:540}, to call the {npc:10041} (level 56)."] = "Usa el {item:11833} donde marca la flecha, dentro de la colmena Gorishi de {area:540}, para llamar a {npc:10041} (nivel 56).",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Usa {item:12928} con {npc:7583}, la niña goblin de {area:976}. A {npc:10977} y {npc:10978} se les asusta más adelante en la ruta.",
		["ten for each quest: {npc:15306} takes his ten before Ortell"] = "diez para cada misión: {npc:15306} recibe los suyos antes que Ortell",
		["{area:976} first, then {zone:1451}, Un'Goro and back to {zone:1446}."] = "Primero {area:976}, luego {zone:1451}, Un'Goro y de vuelta a {zone:1446}.",
		["{area:976} flight master"] = "Maestro de vuelo de {area:976}",
		["{item:20377} from {npc:11739}, 130 yd south-west"] = "{item:20377} de {npc:11739}, a 130 m al suroeste",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} te envía con {npc:9298} en {zone:1452}: guárdala.",
		["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741} da vueltas por {area:2738}: búscalo dentro del círculo del mapa",
		["{npc:11803} walks the Vanguard camp in the far south-west. Keep every {item:20404} the cultists drop: {npc:15306} and Ortell want ten each later."] = "{npc:11803} recorre el campamento de la Vanguardia del extremo suroeste. Guarda todos los {item:20404} que suelten los fieles: {npc:15306} y Ortell quieren diez cada uno más adelante.",
		["{npc:11804} stands in the outpost west of {area:3425}. Keep any Encrypted Twilight Texts that drop here too."] = "{npc:11804} está en el puesto al oeste de {area:3425}. Guarda también los Textos crepusculares codificados que caigan aquí.",
		["{npc:15171} and {npc:15170} camp at Bronzebeard's Encampment, just north of the satchel's mountains. Question them: go through each one's whole conversation; there is no need to fight them."] = "{npc:15171} y {npc:15170} acampan en el Campamento de Barbabronce, justo al norte de las montañas de la cartera. Interrógalos: recorre toda la conversación de cada uno; no hace falta pelear con ellos.",
		["{npc:15189} and {npc:15190} stand upstairs in their building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} y {npc:15190} están en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} ocupa el campamento del oeste.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, en el lado oeste del Fuerte",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} en {zone:1456}; {zone:1454} no tiene instructor de paladines",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} acampa junto al camino de {area:1336}, al sur de {area:976}.",
		["{npc:9117}, below ground"] = "{npc:9117}, bajo tierra",
		["{npc:9299} has already met you: drink the {item:11243} at the graveyard just east of {area:976} and find him, as a ghost, in the rocky crevice due north of it."] = "{npc:9299} ya te ha conocido: bebe {item:11243} en el cementerio justo al este de {area:976} y búscalo, como espíritu, en la grieta rocosa justo al norte.",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "La guarida de {npc:9684} está justo al sur del pilón. Usa allí el cebo de {npc:9619}; {npc:9684} es de nivel 56 y pega fuerte, así que empieza con la salud al máximo.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} está sentado en la cresta, perdido y agotado.",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} se entrega a {npc:8737} en el Cráter de Un'Goro: guárdala.",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451}: mata a estos según te los encuentres",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Vuelve al túnel de los Fauces de Madera y toma la salida de {zone:1452}; {npc:9298} acampa junto a las aguas termales, justo fuera.",
		["Below ground"] = "Bajo tierra",
		["Class trainer"] = "Instructor de clase",
		["Fly to {area:431}"] = "Vuela a {area:431}",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Vuela a {area:431} y cabalga hacia el noroeste por el camino que sale de {zone:1440} y entra en {zone:1448}. {area:2479} es el campamento de los druidas justo pasada la frontera.",
		["Frostfire Winterfall camp"] = "Campamento Nevada de los Baños de Fuego de Escarcha",
		["Ice Thistle yetis"] = "Yetis Cardo Nevado",
		["In the {object:172961}."] = "En {object:172961}.",
		["North of Donova, at the tunnel's {zone:1452} exit."] = "Al norte de Donova, en la salida del túnel hacia {zone:1452}.",
		["Ride back west along the road to {area:2246}."] = "Vuelve al oeste por el camino hasta {area:2246}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Cabalga hacia el norte por el camino, dejando atrás {area:1763}, hasta {area:1997}.",
		["Ride north to {area:2255}."] = "Cabalga al norte hasta {area:2255}.",
		["Scare {npc:10978} with {npc:10980}"] = "Asusta a {npc:10978} con {npc:10980}",
		["The runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Los mensajeros caminan por el camino de {area:1769} hacia {area:2244} en pequeños grupos; espera junto al camino cerca de {npc:9298} y mátalos al pasar. Cada uno lleva una caja.\nCuidado: al entregar aparecen tres o cuatro emboscadores de los Cuna Invernal de nivel 56-57 que te atacan; puedes escapar de ellos montado, en sigilo o con {spell:5384}, y luego se reúnen junto al lago para que puedas tomar la siguiente misión.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Cruza el túnel de los Fauces de Madera hasta {zone:1450}. {npc:11939} lee en una casa de {area:2361}.",
		["Trey Lightforge's remains lie at the edge of the {area:1763} camp, west of the road: they go back to {npc:11019} at the end of this guide."] = "Los restos de Trey Lightforge están en el borde del campamento de {area:1763}, al oeste del camino: vuelven a {npc:11019} al final de esta guía.",
		["With 30 {quest:6031} in your bags: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Con 30 de {quest:6031} en tus bolsas: sigue el camino hacia el norte hasta {area:1769}; {npc:11557} comercia justo al pasar la entrada.",
		["grind on {npc:7446}"] = "mata {npc:7446}",
		["sixty {item:14047}"] = "sesenta {item:14047}",
		["{npc:11556} takes the beads only once {quest:8464} is handed in: any Winterfall furbolg can carry them, and the camps just south of {npc:11556} are the closest."] = "{npc:11556} solo acepta las cuentas una vez entregada {quest:8464}: cualquier fúrbolg Nevada puede llevarlas, y los campamentos justo al sur de {npc:11556} son los más cercanos.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} da vueltas por aquí: mira dentro del círculo del mapa",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Fragmentos de gangrevid, de {npc:11801}, requiere {area:2577}. Omítela.",
		["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} da vueltas por {area:2361}: búscalo dentro del círculo del mapa",
		["{npc:9116}, inside"] = "{npc:9116}, dentro",
		["{quest:8464}'s village is north-east of {area:2255}, on this guide's way back from {area:2256}."] = "El poblado de {quest:8464} está al noreste de {area:2255}, en el camino de vuelta de esta guía desde {area:2256}.",
		["{zone:1454} flight master"] = "Maestro de vuelo de {zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Los escórpidos acorazados se arrastran por las llanuras al oeste de {area:362}. Domestica uno y vuelve con {npc:3171}.",
		["Back east to Sen'jin on the way to the {area:368}."] = "Vuelve al este, al poblado Sen'jin, de camino a {area:368}.",
		["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "De vuelta al noroeste, a {area:362}: primero {npc:3139}, luego {npc:3147} en la atalaya, y después {npc:3142} y {npc:266940} de salida al este hacia la orilla.",
		["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Vuelve a cruzar el puente y ve al sur por la orilla de {zone:1411} del río hasta donde un sendero angosto sube la montaña: {npc:5900} cuida el santuario de la cima. Cuidado con los bordes al subir, y baja por el mismo sendero.",
		["Back to the Den"] = "Vuelve a El Cubil",
		["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Vuelve a la Guarida: {npc:3143} recoge la garra de {quest:804} y {npc:5887}, justo fuera, tiene {quest:1516} ahora que eres de nivel 4.",
		["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "De vuelta a {area:362}: {npc:3139} y luego {npc:3142}.",
		["Back to {zone:1411}"] = "De vuelta a {zone:1411}",
		["Below ground"] = "Bajo tierra",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Los fieles Filo Ardiente ocupan las cuevas de {quest:827}; cualquiera de ellos suelta {item:4871}. {npc:3204}, un brujo de nivel 14, está en lo más hondo y suelta {item:4903}.\nCuidado: los abisarios luchan junto a los fieles Filo Ardiente en {quest:827} y {npc:3204} (14) espera al fondo con el suyo: atrae a un fiel cada vez cerca de la entrada para los collares. {item:4903} es opcional: deja a {npc:3204} en paz salvo que seas de nivel 13 o vayas con un amigo.",
		["Careful: Ukorsbane (8) is elite and walks among the Ridgeshade spiders in the camp south of {area:362}: pull the spiders away from him."] = "Cuidado: Ukorsbane (8) es élite y anda entre las arañas Sombracresta en el campamento al sur de {area:362}: atrae a las arañas lejos de él.",
		["Class trainer"] = "Instructor de clase",
		["Deathskip to Northern Durotar"] = "Muere para volver rápido al norte de Durotar",
		["Deathskip to {area:367}"] = "Muere para volver rápido a {area:367}",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Muere ante los enemigos en 52.0,21.4 ({npc:3118}): morir ahí te manda a este cementerio. Libera tu espíritu y acepta la resurrección del {npc:6491}.",
		["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Muere ante los enemigos en 66.9,87.2 ({npc:3206}): morir ahí te manda a este cementerio. Libera tu espíritu y acepta la resurrección del {npc:6491}.",
		["Druid trainer"] = "Instructor de druidas",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Los acechadores viles recorren la ladera bajo la cueva, en el lado norte del valle.",
		["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle ocupa el campamento del Filo Ardiente en {area:369}, justo al norte de la choza de Misha. Cazadores: domestica un {npc:3099} con la {item:15908} por el camino.\nCuidado: los fieles del Filo Ardiente rodean a Fizzle, algunos vinculados, así que atacan por parejas, y reaparecen rápido.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: localízalo antes de atraer.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libera a {npc:275811} y sácala sana y salva del risco",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Ve al noreste hasta el camino hacia {zone:1454}. {npc:3293} acampa a su lado; los sacos robados están a lo largo del camino al sur de él.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle.\nCareful: the trolls stand close together and the Voodoo Trolls cast from range: pull one at a time. {quest:826} himself is level 10."] = "Ve al sur por las islas. Los ídolos loa están por todas las islas del sur; los trols vudú y los trols embrujados los llevan y sueltan los colgantes embrujados. {quest:826} y la jaula de Minshina están en la isla más al sur.\nCuidado: los trols están muy juntos y los trols vudú lanzan hechizos a distancia: atráelos de uno en uno. El propio {quest:826} es de nivel 10.",
		["Inside"] = "Dentro",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro de la cueva, sigue recto en la primera bifurcación, luego a la derecha, y sigue el arroyo que tienes a la izquierda hasta la cascada: el pico brilla junto al agua, detrás de una columna de roca.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro de la cueva, sigue la pared derecha durante todo el recorrido, cruzando el arroyo: {npc:3183} espera al final.",
		["Level 10"] = "Nivel 10",
		["Level 11"] = "Nivel 11",
		["Level 7"] = "Nivel 7",
		["Level 9"] = "Nivel 9",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La choza de Misha está al sur de los lagartos. Los crocoliscos de {area:814}, al oeste, llevan {item:4891}.",
		["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "Al noreste, a la playa bajo {area:370}, al norte de {npc:275657}: la ocupan los exploradores y ayudantes Látigo de Ira. Cazadores: domestica un {npc:3107} en la playa.",
		["Paladin trainer"] = "Instructor de paladines",
		["Quilboars and scouts hold the huts west of town, where the prickly pears grow; dustrunners and battleguards hold the camps farther west."] = "Los jabaespines y exploradores ocupan las chozas al oeste del pueblo, donde crecen los higos chumbos; los correpolvos y guardias de batalla ocupan los campamentos más al oeste.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Los salvajes y las brujas de la tormenta anidan en {area:370}, al este de {npc:3293}. Una bruja de la tormenta suelta {item:277661}. Chamanes: los fieles Filo Ardiente junto a {area:371}, en el extremo sur del barranco, sueltan {item:6652}.",
		["Spitelash naga"] = "Nagas Látigo de Ira",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The Scorpid Workers roam the slope south of {npc:3287}; pick the Cactus Apples by the cactuses on the way.\nThe {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "Los trabajadores escórpidos recorren la ladera al sur de {npc:3287}; recoge las manzanas de cactus junto a los cactus por el camino.\nLos {quest:792} abundan en la ladera bajo {area:365}, la cueva del lado norte del valle.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Las espadañas y la hierba lanza crecen junto al agua en {object:172958}, al este de La Calle Mayor.",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin.\nMakrura and surf crawlers line the beaches north-east of Sen'jin."] = "Las cajas de herramientas gnomas están entre los restos a lo largo de la orilla al este y sureste de {area:362}. Sigue la orilla al sur hasta Sen'jin.\nLos makrura y los reptadores de la marea ocupan las playas al noreste de Sen'jin.",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}."] = "El fuerte está en la costa, al sureste de {area:362}. El hacha, el arco y el escudo de asaltante están en sus alrededores. Los marineros y los soldados de marina sueltan {item:4870}.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Las armas están alrededor de El Cubil y del campo de entrenamiento; los jabalíes jaspeados recorren todo el fondo del valle.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} está en {area:817}, entre los fieles con los que acabas de luchar.",
		["Through Sen'jin on the way west to {area:366}: {npc:3304} takes the eyes and mucus now."] = "Pasa por el poblado Sen'jin de camino al oeste hacia {area:366}: {npc:3304} recoge ya los ojos y la mucosidad.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los truenagartos y los lomorrayos pastan en {area:369}, junto al camino al norte hacia {zone:1454}; cualquiera de ellos puede soltar {item:6486}. {npc:5810} la recoge cuando la siguiente guía pasa por {area:379}.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: localízalo antes de atraer.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Los truenagartos y los lomorrayos pastan en {area:369}, justo al oeste y suroeste de {npc:3293}.\nCuidado: Halikor, un élite de nivel 12, recorre {area:369} entre los lagartos: localízalo antes de atraer.",
		["Thunder lizards on the way north"] = "Truenagartos de camino al norte",
		["To {zone:1454}"] = "A {zone:1454}",
		["Top up here to level 11 before {npc:3203} (12) and his imp: the Thunder Lizards (9-10) graze on the ridge just west of Misha's hut."] = "Sube aquí hasta el nivel 11 antes de {npc:3203} (12) y su diablillo: los truenagartos (9-10) pastan en el risco justo al oeste de la choza de Misha.",
		["Top up here to level 7 before {npc:3192} (8) and the marines at the top of the keep."] = "Sube aquí hasta el nivel 7 antes de enfrentarte a {npc:3192} (8) y a los soldados de marina de lo alto del fuerte.",
		["Top up here to level 9 before the southern isles: the Voodoo and Hexed Trolls there are 8-9 and {quest:826} is 10."] = "Sube aquí hasta el nivel 9 antes de las islas del sur: los trols vudú y los trols embrujados de allí son de nivel 8-9 y {quest:826} es de nivel 10.",
		["Training weapons and boars"] = "Armas de entrenamiento y jabalíes",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Piso de arriba",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Cruza vadeando hasta la isla del Eco del norte. La matriarca merodea allí entre los raptores.\nLos tigres de Durotar recorren la isla y también la orilla al sur del poblado Sen'jin, y los huevos de coleador están en nidos en las islas y a lo largo de la playa.",
		["Wake {quest:5441} with the {item:16114}"] = "Despierta a los {quest:5441} con {item:16114}",
		["West from {area:362} over the {area:814} bridge: {npc:3337} and {npc:5810} stand together at {area:379} above it. From there the road north through {zone:1411} leads to {zone:1454}."] = "Al oeste desde {area:362} por el puente de {area:814}: {npc:3337} y {npc:5810} están juntos en {area:379}, encima. Desde ahí, el camino al norte por {zone:1411} lleva a {zone:1454}.",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Al oeste por el puente de {area:814}, pasando {area:379} y siguiendo por la cresta: {npc:5907} está solo sobre el campamento Crines de Acero.",
		["West over the {area:814} bridge: {npc:3337} stands at {area:379} above it, on your way to {npc:5907}."] = "Al oeste por el puente de {area:814}: {npc:3337} está en {area:379}, encima, de camino a {npc:5907}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Ya que estás aquí: aprende Bastones con {npc:2704} ({object:172958}, 10 de plata); el arma cuerpo a cuerpo de un cazador vale sobre todo por sus estadísticas, y las de dos manos son las que más tienen.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Ya que estás aquí: aprende Bastones con {npc:2704} ({object:172958}, 10 de plata); un bastón da más estadísticas de hechizo que un arma de una mano mientras subes de nivel.",
		["grind on {npc:3111}"] = "mata {npc:3111}",
		["grind on {npc:3121}"] = "mata {npc:3121}",
		["grind on {npc:3128}"] = "mata {npc:3128}",
		["grind on {npc:3130}"] = "mata {npc:3130}",
		["the {object:654925} on the ground beside her"] = "{object:654925}, en el suelo a su lado",
		["{area:363}: kill these as you meet them"] = "{area:363}: mátalos según te los encuentres",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} está al oeste del poblado Sen'jin. Los tres planes de ataque están en el suelo entre las tiendas de los centauros. {npc:275811} también está presa en el risco.",
		["{area:368}: kill these as you meet them"] = "{area:368}: mátalos según te los encuentres",
		["{area:369}: kill these as you meet them"] = "{area:369}: mátalos según te los encuentres",
		["{area:373}: kill these as you meet them"] = "{area:373}: mátalos según te los encuentres",
		["{area:817}'s mouth"] = "Entrada de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, donde empiezas",
		["{npc:11025} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:11025} la recoge en cuanto tu habilidad de {skill:202} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, en la pila de madera al este de la Guarida",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} en {zone:1456}; {area:362} no tiene instructor de paladines",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} en {zone:1456}; {area:363} no tiene instructor de paladines",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362}, by {area:367} for fishing, or in {zone:1454} at the start of the next guide."] = "{npc:265809} acampa justo al sur de {area:362}. Siéntate junto a su hoguera (/sit) hasta que aparezca el beneficio {spell:1229451}. Con una profesión aprendida, {npc:265809} también ofrece su Campamento 101, que recoge su instructor: en {area:362}, junto a {area:367} para la pesca, o en {zone:1454} al principio de la siguiente guía.",
		["{npc:265809}'s campfire"] = "La hoguera de {npc:265809}",
		["{npc:265809}: for Jandi"] = "{npc:265809}: para Jandi",
		["{npc:265809}: for Jhag"] = "{npc:265809}: para Jhag",
		["{npc:265809}: for Karolek"] = "{npc:265809}: para Karolek",
		["{npc:265809}: for Snang"] = "{npc:265809}: para Snang",
		["{npc:265809}: for Thuwd"] = "{npc:265809}: para Thuwd",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}: para {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}: para {npc:11046}",
		["{npc:265809}: for {npc:3174}"] = "{npc:265809}: para {npc:3174}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}: para {npc:3175}",
		["{npc:265809}: for {npc:5941}, on the shore south of Sen'jin"] = "{npc:265809}: para {npc:5941}, en la orilla al sur de Sen'jin",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}: para {npc:5943}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: solo encantadores; el residuo se obtiene desencantando colgantes embrujados",
		["{npc:266940}, inside"] = "{npc:266940}, dentro",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, en el lado este del pueblo; adentro",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} está en la orilla, al este de {area:362}. El tridente, el estandarte y la daga están en la playa a su alrededor.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un joven gigante marino, recorre la costa norte de {zone:1411}, al norte de la playa de los nagas. {npc:275666} es élite: se recomienda agruparse.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} en {zone:1412}; {area:362} no tiene instructor de druidas",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} en {zone:1412}; {area:363} no tiene instructor de druidas",
		["{npc:3102} hooves"] = "Pezuñas de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de vuelta en {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, un gigante de mar élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} está nada más entrar en la cueva; {npc:3159}, al fondo de la cueva, detrás de él.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} espera dentro de El Cubil, el edificio justo al oeste de {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, dentro",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, en la atalaya",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, el instructor de guerreros, junto a El Cubil",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, el instructor de cazadores, junto a El Cubil",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, el instructor de pícaros, en El Cubil",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, el instructor de brujos, al fondo de la cueva",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, el instructor de chamanes, junto a El Cubil",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, al fondo de la cueva; bajo tierra",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}: {npc:3352} en {zone:1454} enseña {spell:5149}",
		["{npc:3174} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3174} la recoge cuando tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:3175} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3175} la recoge en cuanto tu habilidad de {skill:186} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191}: Campamento 101 te pide aprenderla",
		["{npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "{npc:3192} espera en lo alto del fuerte; su llave abre el cofre que tiene al lado, que contiene {item:4881}.",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} yace herido al pie de las colinas, al noroeste de El Cubil.",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it.\nCareful: the voidwalker you summon hits hard and it is the fight Warlocks die to most in {zone:1454}: start at full health and mana, send your imp in, keep Corruption and Immolate on it, and use a healthstone if you have one."] = "{npc:5875} está en {object:172960}, el cañón bajo {object:172982}. Entrégale {item:6535}, luego usa {item:7464} en el círculo de invocación junto a él y derrota al abisario para vincularlo.\nCuidado: el abisario que invocas pega fuerte y es el combate en el que más mueren los brujos en {zone:1454}: empieza con la salud y el maná al máximo, manda a tu diablillo por delante, mantén Corrupción e Inmolar sobre él y usa una piedra de salud si tienes una.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, el instructor de magos en Sen'jin",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, la instructora de magos, en la entrada de El Cubil",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} está fuera de El Cubil. {area:639} es la colina justo al sur: bebe {item:6635} allí para ver a {npc:5891} y lleva {item:6656} a {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} y tu {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, en {area:639}",
		["{npc:5941} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5941} la recoge cuando tu habilidad de {skill:356} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:5943} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5943} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} está en el camino, en la salida este del valle.",
		["{npc:6928}, inside"] = "{npc:6928}, dentro",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, junto al fuego de cocina",
		["{quest:790}, a large scorpid (level 4), prowls the slope just west of the Den, below {npc:3287}, on the way north to the {area:365}."] = "{quest:790}, un gran escórpido (nivel 4), merodea por la ladera justo al oeste de la Guarida, bajo {npc:3287}, de camino al norte hacia {area:365}.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} acampa en la colina al oeste de la playa de los naga, al sur de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La puerta principal de {zone:1454} está justo al oeste de {area:817}. {npc:5875} está en {object:172960}, el cañón bajo {object:172982}.",
		["{zone:1454}'s {object:172982}"] = "{object:172982} de {zone:1454}",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sentarse junto a la hoguera de {npc:263664} hasta obtener {spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders y los guardias caídos están justo al suroeste de la torre. Coge la Pluma de la suerte de Raani y el sello Cantosombrío de los cuerpos.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De vuelta en {quest:92529}: Clamatormentas Al'Aketh y {npc:251662} llenan el pueblo, los Cajones de provisiones están entre las casas y {npc:251966} espera en su extremo sureste.",
		["Back to Boro in {area:16635} with the Signet."] = "Vuelve con Boro en {area:16635} con el Sello.",
		["Back to {area:16635}"] = "De vuelta a {area:16635}",
		["Back to {area:16638}"] = "De vuelta a {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Vuelve con {npc:268592}. Espera a que encienda el {npc:268762} y lleva la llama directamente al {npc:268679}, junto a {npc:252382} en {area:16638}, antes de que se acabe el tiempo.",
		["Back up from the den to {npc:257551} and {npc:251366} in the village before heading south-west to {npc:252095}: the road from her camp leads on south to Shen'dar."] = "Vuelve a subir desde la guarida hasta {npc:257551} y {npc:251366} en la aldea antes de ir al suroeste con {npc:252095}: el camino desde su campamento sigue al sur hasta Shen'dar.",
		["Below ground"] = "Bajo tierra",
		["Boro and {npc:251373}, while you stand beside them"] = "Boro y {npc:251373}, mientras estés a su lado",
		["Cast {spell:1259686} near the {object:460001}"] = "Lanza {spell:1259686} cerca de {object:460001}",
		["Class trainer"] = "Instructor de clase",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village. {quest:93159} has his own for engineers."] = "Sigue el camino al sur hasta {area:16624}, en el centro de la isla. {npc:251523} está en su lado este, {npc:251902} en el centro, {npc:254089} justo al noroeste de ella, {npc:263664} junto a la hoguera del lado oeste. Con una profesión aprendida, {npc:263664} también ofrece su Campamento 101: su instructor está en el poblado. {quest:93159} tiene el suyo para ingenieros.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Ve al norte hacia {area:16631}; {npc:257944} acampa en su borde sur.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Ve al noreste hasta {area:17675}. El campamento Al'Aketh está justo al oeste, con {npc:252666} en su extremo norte. Cualquier cultista puede soltar un Talismán de piedra de viento de Al'Aketh.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Ve al suroeste hasta {area:17674}. {npc:252155} está arriba; la {item:254871} está a su lado.",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la Guarida Colmillo Nocturno",
		["Hungry Bandits"] = "Bandidos hambrientos",
		["Innkeeper {npc:255940}, by the west gate"] = "El posadero {npc:255940}, junto a la puerta oeste",
		["Into {zone:1412}"] = "Hacia {zone:1412}",
		["Into {zone:1413}"] = "Hacia {zone:1413}",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Salta desde lo alto de la atalaya y usa {spell:1259416} para bajar flotando hasta {npc:251361}, al oeste de la torre.",
		["Learn the flight path from {npc:3615} on the tower platform. {area:380}' own quests come after {zone:1421}, in the {zone:1413} guide."] = "Aprende la ruta de vuelo con {npc:3615} en la plataforma de la torre. Las misiones propias de {area:380} vienen después de {zone:1421}, en la guía de {zone:1413}.",
		["Leave {zone:2521} to {zone:1412}"] = "Sal de {zone:2521} hacia {zone:1412}",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:256083}"] = "Escucha a {npc:256083}",
		["Northern {zone:1412}"] = "Norte de {zone:1412}",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "En el camino al sureste hacia {area:16638}, {npc:273017} vigila a {quest:98512}, justo al norte de él.",
		["On your way north from Valennia, {npc:255853} waits by the falls north-east of you, just north of the {area:17675}: from the ridge above them, glide down with {spell:1259416}."] = "De camino al norte desde Valennia, {npc:255853} espera junto a las cascadas al noreste, justo al norte de {area:17675}: desde la cresta de arriba, planea hasta abajo con {spell:1259416}.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Moscas de cirro molestas y {npc:250873} deambulan por la arboleda justo al sureste del pueblo.",
		["Portal to {area:16630}"] = "Portal a {area:16630}",
		["Prideclaws and Galestriders share the meadows around {area:16624}; the Galestriders graze thickest just west of it. They drop both the Small Eggs and the {item:5469} for {npc:251905}."] = "Las garramanadas y los Galestrid comparten los prados alrededor de {area:16624}; los Galestrid pastan más justo al oeste. Sueltan tanto los Huevos pequeños como {item:5469} para {npc:251905}.",
		["Raw Windstones"] = "Piedras de viento en bruto",
		["Ripe Stormapples"] = "Manzanas tempestuosas maduras",
		["Shen'dar bounty board"] = "Tablón de recompensas de Shen'dar",
		["Skyhoppers"] = "Saltanubes",
		["Skyhoppers hop about the fields just west of Valennia."] = "Los Saltanubes brincan por los campos justo al oeste de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Esparce el {item:278078} desde {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Hay Manzanas tempestuosas y Polvo de alabatiente por todo el huerto; los Bandidos hambrientos lo saquean. Los Zancavendavales pastan en los campos al este. El autómata roto flota en el borde norte del huerto.",
		["Take the Portal to {area:16630} in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell {npc:252475} you are ready. Leave the {object:617084} up there alone until Rohash has withdrawn; then it takes you straight back to town."] = "Toma el Portal a {area:16630} en el santuario para subir a las alturas. Avanza peleando al este por la cornisa hasta los pacificadores del final, sube con la corriente de viento a la terraza superior y dile a {npc:252475} que estás listo. No toques {object:617084} de arriba hasta que Rohash se haya retirado; después te lleva directo de vuelta al pueblo.",
		["Take {item:277267} to {npc:268592} at the Shrine of Flames, south-west of {area:16638}, then head west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Lleva {item:277267} a {npc:268592} en el Santuario de las Llamas, al suroeste de {area:16638}, y luego ve al oeste hacia {area:16623}: el hogar de {npc:268605} está en las colinas al sur de los lagos de los reptadores Canzalvaje.",
		["Take {zone:1456}'s west lift down: the road at its foot runs south-east across {zone:1412} to the {zone:1413}."] = "Baja por el elevador oeste de {zone:1456}: el camino al pie va al sureste por {zone:1412} hasta {zone:1413}.",
		["Tame {npc:250874}"] = "Domestica un {npc:250874}",
		["Tame {npc:251707}"] = "Domestica un {npc:251707}",
		["Tame {npc:254588}"] = "Domestica un {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Al'Aketh camp"] = "El campamento Al'Aketh",
		["The Enchanted Gyrozephyrs lie under water far to the north, east of {area:16624} and south-west of {area:16625}."] = "Los Girocéfiros encantados están bajo el agua, lejos al norte, al este de {area:16624} y al suroeste de {area:16625}.",
		["The Highwayman Bandits hold the hills north of {area:16663}; they drop the Blood-Stained Bandit Masks."] = "Los salteadores bandidos ocupan las colinas al norte de {area:16663}; sueltan las Máscaras de bandido manchadas de sangre.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Las Piedras de viento en bruto son cristales azules en las laderas alrededor del pueblo.",
		["The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Los aprendices practican al noreste del pueblo.\nLos campamentos de bandidos están al noreste del pueblo; \"Malabrisa\" Bennic ocupa el campamento de arriba. Los bandidos llevan las piedras de viento robadas.",
		["The hermit lives at {area:16625}'s west shore."] = "El ermitaño vive en la orilla oeste de {area:16625}.",
		["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "Los nidos de hipogrifo están al noroeste de {area:17674}, al oeste de {quest:92529}. La matriarca está en su extremo oeste; hay {item:263493} en el suelo alrededor de los nidos.",
		["The orchard"] = "El huerto",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La Reina mosca de cirro revolotea en el extremo sureste de la arboleda, de camino de vuelta de las piedras.",
		["The road from {zone:1412} meets the {area:458} at {area:378}: {npc:10378}, the wind rider master, stands beside {npc:3418} on your way north to the Crossroads."] = "El camino de {zone:1412} se une a {area:458} en {area:378}: {npc:10378}, el maestro de jinetes del viento, está junto a {npc:3418} de camino al norte hacia el Cruce.",
		["The standing stones"] = "Las piedras erguidas",
		["The turncoat"] = "El traidor",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}, just north of {npc:273017}."] = "La casa del traidor está en {area:16626}, al noroeste de {area:16638}, justo al norte de {npc:273017}.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} está al norte de {area:16638}. Ábrete paso entre los guardias hasta {npc:253576}, en su lado este.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {item:260881} lies in a cave in the hills north-west of {npc:256083}."] = "{item:260881} está en una cueva en las colinas al noroeste de {npc:256083}.",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "A {zone:1454}",
		["Underwater"] = "Bajo el agua",
		["Upstairs"] = "Piso de arriba",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Usa el {item:278078} en la esterilla ceremonial y el quemador del acantilado sur de {area:1641}.",
		["Valennia asks you to hear out both leaders: {npc:251968} of the Horde and {npc:252475} of the Alliance. {npc:252475}'s name shows red to you, but he talks to you all the same, and the quest needs both."] = "Valennia te pide que escuches a ambos líderes: {npc:251968} de la Horda y {npc:252475} de la Alianza. El nombre de {npc:252475} te aparece en rojo, pero habla contigo igualmente, y la misión necesita a ambos.",
		["Warlock trainer"] = "Instructor de brujos",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Ya que estás aquí: aprende Bastones con {npc:11869} (10 de plata); el arma cuerpo a cuerpo de un cazador vale sobre todo por sus estadísticas, y las de dos manos son las que más tienen.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Ya que estás aquí: aprende {spell:199} con {npc:11869} (10 de plata); las armas de dos manos hacen subir de nivel más rápido a un guerrero.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Dejas la isla para siempre. {npc:259119} espera donde aterriza la aeronave.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Despiertas en {area:16635}, al norte de la isla. {npc:251362} está junto al sendero y {npc:251361} en el centro del pueblo.",
		["drink the {item:6635} at the {area:16988}, just east of the village, to see the {npc:251166}"] = "bebe la {item:6635} en {area:16988}, justo al este del pueblo, para ver la {npc:251166}",
		["search the dead cultist in the house"] = "registra al cultista muerto de la casa",
		["search the wardrobe"] = "registra el armario",
		["talk to the {npc:251684}"] = "habla con {npc:251684}",
		["talk to {npc:251684}"] = "habla con {npc:251684}",
