		["Beasts 10-19: {zone:1439} (50-100)"] = "Bestias 10-19: {zone:1439} (50-100)",
		["Beasts 19-20: {zone:1431} (100-125)"] = "Bestias 19-20: {zone:1431} (100-125)",
		["Beasts 19-21: {zone:1440} (100-125)"] = "Bestias 19-21: {zone:1440} (100-125)",
